// deps: 4948, 46173, 99808, 27214, 14029, 75435, 34988, 29979, 83593, 10414, 84726, 20544, 74738, 33922, 29804, 30610, 33058, 7404, 89095, 90149, 2085, 88351, 28457, 52431, 17526, 45546
const module_6480 = (e,a,n)=>{"use strict";n.r(a),n.d(a,{default:()=>A});var i=n(4948),t=n(46173),r=n(99808),o=n(27214),s=n(14029),l=n(75435),d=n(34988),c=n(29979),u=n(83593);let m=JSON.parse('[{"key":"tangtang","name":"Tangtang","codename":"Tangtang","camp":"Endfield Industries","race":"Felin","rarity":6,"intro":"„Der Oberh\xe4uptling ist da! Du, du und du, ihr untersteht alle meinem Kommando!“\\nTangtang ist Oberh\xe4uptling der Qingbo-Palisade. Sie ist sehr direkt, Treue ist ihr sehr wichtig und sie handelt stets frei und ungebunden aus dem Bauch heraus. Sie liebt die Freiheit und spielt gerne im Wasser, hasst es aber, verraten zu werden. Wenn sie dich einmal zu ihren Freunden z\xe4hlt, wird sie kaum eine M\xfche scheuen, um dich zu unterst\xfctzen.\\nAls kleines Kind wurde Tangtang von einer unbekannten Person in ein Bambusk\xf6rbchen gelegt und von der Str\xf6mung des Flusses zur Qingbo-Palisade getrieben. Dort adoptierten die Palisadeure sie und machten sie zu einem Mitglied ihrer Familie. Viele sehen in ihr noch ein Kind, das man verw\xf6hnen sollte, aber tief im Inneren ist sie bereits fest entschlossen, die Last der Verantwortung f\xfcr die Zukunft der Qingbo-Palisade zu tragen.\\nKeiner der R\xfcckschl\xe4ge, die sie erleben musste, konnte ihre Hingabe zu ihrer Welt schm\xe4lern. Tangtang hat sich Endfield Industries angeschlossen, um Antworten auf ihre Fragen zu finden und um die Entwicklung der Qingbo-Palisade vorantreiben zu k\xf6nnen.\\n„Sorg daf\xfcr, dass sie niemals in die N\xe4he von Mi Fu kommt, sonst gibt es Sachsch\xe4den.“ Diese Warnung stammt von einem Operator aus der Logistik-Hauptabteilung.\\n„Hast du mich nur hergerufen, um mir ein Lob auszusprechen? Na, dann leg noch eins drauf! Ich liebe es, die Wahrheit zu h\xf6ren!“","prof":"caster","elem":"ice","cv":{"en-us":"Jing Chen"}},{"key":"rossi","name":"Rossi","codename":"Rossi","camp":"Endfield Industries","race":"Lupo","rarity":6,"intro":"„Ein Kinderspiel f\xfcr jemanden wie mich!“\\nRossina Wulfperl Luppino, Wulfgards j\xfcngere Schwester und die Perle des Rudels. In einer Fehde mit den Knochenbrechern zahlten viele Wolfs\xe4lteste einen blutigen Preis, um sie in Sicherheit zu bringen. An diesem Tag f\xe4rbte das Blut ihre Wickeldecke rot …\\nWulfgard agiert schon seit Jahren unabh\xe4ngig vom Klan, aber das Rudel brauchte einen Anf\xfchrer, und Rossi nahm diese Verantwortung auf sich. Eigentlich ist sie der Ansicht, dass ihr Bruder, der bereits in jungen Jahren Ruhm erlangte, das gesamte Rudel anf\xfchren sollte. Sie wird niemals m\xfcde, ihn nachdr\xfccklich daran zu erinnern und dazu aufzufordern. Die \xc4ltesten des Klans w\xfcrden gern sehen, wie Rossi sich mehr ihrem Alter entsprechend verh\xe4lt und mehr Zeit damit verbringt, ihren Leidenschaften nachzugehen. Rossi jedoch kann die Last der „Verantwortung“ niemals von ihrem Herzen nehmen und ist stets bem\xfcht, zum Wohle ihrer Familie und des Klans noch verl\xe4sslicher und st\xe4rker zu werden.\\nInsgeheim sehnt Rossi sich danach, Teil einer Heldensage zu sein und tr\xe4umt davon, irgendwann an der Seite eines legend\xe4ren Helden zu k\xe4mpfen. Daf\xfcr gew\xe4hrt sie sich ab und an kleine Auszeiten.\\n„Die Bisse waren wirklich heftig, aber das Rudel hat keine Angst vor weiteren Narben!“","prof":"guard","elem":"physic","cv":{"en-us":"Giada Sabellico"}},{"key":"endministrator2","name":"Endministrator","codename":"Endministrator","camp":"Endfield Industries","race":"Unter Verschluss","rarity":6,"intro":"Der Endministrator von Endfield Industries.\\nIn der aufgezeichneten Geschichte von Talos-II \xfcbernimmt der Endministrator die Rolle eines obersten W\xe4chters. Er besch\xfctzt die Zivilisation auf diesem Planeten und bewahrt die Menschheit vor mehreren verheerenden Katastrophen. Die Taten des Endmin haben eine Vielzahl von Geschichten, Erz\xe4hlungen und sogar Ger\xfcchten hervorgebracht. \\nDie Identit\xe4t des Endmin ist jedoch nach wie vor schwer nachzuvollziehen und nur eine Handvoll Menschen hat die Legende pers\xf6nlich gesehen. \\nAndere Fraktionen innerhalb des Zivilisationsg\xfcrtels wissen zwar, dass Endfield einen ganz besonderen Trumpf in der Hand h\xe4lt, aber mehr Informationen besitzen sie nicht. \\nDie mysteri\xf6se Meisterung von Originium und des Protokoll-Netzwerks durch den Endministrator sowie die Notwendigkeit des Endmins, in regelm\xe4\xdfigen Abst\xe4nden einen l\xe4ngerfristigen Schlaf einzulegen, z\xe4hlt zu Endfields wichtigsten Geheimnissen.","prof":"guard","elem":"physic","cv":{"en-us":"Hyoie O\'Grady"}},{"key":"endministrator1","name":"Endministrator","codename":"Endministrator","camp":"Endfield Industries","race":"Unter Verschluss","rarity":6,"intro":"Der Endministrator von Endfield Industries.\\nIn der aufgezeichneten Geschichte von Talos-II \xfcbernimmt der Endministrator die Rolle eines obersten W\xe4chters. Er besch\xfctzt die Zivilisation auf diesem Planeten und bewahrt die Menschheit vor mehreren verheerenden Katastrophen. Die Taten des Endmin haben eine Vielzahl von Geschichten, Erz\xe4hlungen und sogar Ger\xfcchten hervorgebracht. \\nDie Identit\xe4t des Endmin ist jedoch nach wie vor schwer nachzuvollziehen und nur eine Handvoll Menschen hat die Legende pers\xf6nlich gesehen. \\nAndere Fraktionen innerhalb des Zivilisationsg\xfcrtels wissen zwar, dass Endfield einen ganz besonderen Trumpf in der Hand h\xe4lt, aber mehr Informationen besitzen sie nicht. \\nDie mysteri\xf6se Meisterung von Originium und des Protokoll-Netzwerks durch den Endministrator sowie die Notwendigkeit des Endmins, in regelm\xe4\xdfigen Abst\xe4nden einen l\xe4ngerfristigen Schlaf einzulegen, z\xe4hlt zu Endfields wichtigsten Geheimnissen.","prof":"guard","elem":"physic","cv":{"en-us":"Chloe Eves"}},{"key":"perlica","name":"Perlica","codename":"Perlica","camp":"Endfield Industries","race":"Liberi","rarity":5,"intro":"„Wir haben einst gek\xe4mpft und nicht aufgegeben … denn wir wollen deine R\xfcckkehr erleben.“ \\nPerlica ist die Aufseherin bei Endfield Industries und die offizielle Sprecherin des Unternehmens. In erster Linie ist sie daf\xfcr verantwortlich, die Entwicklung und Anwendung der Protokoll-Originium-Technologie zu beaufsichtigen und voranzutreiben, w\xe4hrend sie gleichzeitig den Betrieb der Dijiang verwaltet. \\nAls herausragende Expertin f\xfcr Techno-Protokolle hat sie die Forschung geleitet, die einen entscheidenden Einfluss auf die adaptive Entwicklung und Anwendung dieser Technologie hatte. Zudem hat sie dazu beigetragen, den Automatisierten Industriekomplex (AIK-Fabrik) zu verfeinern. \\nSie ist in der Lage, auf unterschiedlichste Krisen ruhig und entschlossen zu reagieren. Allerdings steht Endfield oft vor Herausforderungen, die alle Erwartungen \xfcbersteigen. W\xe4hrend der Endministrator sich im Schlafzustand befand, \xfcbernahm sie das Kommando \xfcber das Krisenteam und f\xfchrte die Helden von Endfield Industries in einen Kampf f\xfcr eine gr\xf6\xdfere Sache. Perlica bewegt sich unerm\xfcdlich durch den Zivilisationsg\xfcrtel und tut alles in ihrer Macht Stehende, um die Ordnung aufrechtzuerhalten und die Dinge am Laufen zu halten. \\n\\n„Nur, wenn wir das Land durchwandern, k\xf6nnen wir jeden Atemzug und jeden Pulsschlag des Lebens sp\xfcren … genau daf\xfcr k\xe4mpft Endfield.“","prof":"caster","elem":"electric","cv":{"en-us":"Jane Jackson"}},{"key":"chen","name":"Chen Qianyu","codename":"Chen Qianyu","camp":"Endfield Industries","race":"Lung","rarity":5,"intro":"„Nun, es hat sich herausgestellt, dass ich auch noch etwas anderes als Kampfk\xfcnste gut beherrsche. Ich kann einfach nicht anders, als deine beste Operatorin zu werden.“ \\nChen Qianyu ist eine Operatorin bei Endfield Industries und ein Kernmitglied des Krisenteams. \\nSchon in jungen Jahren trainierte sie unter Anleitung ihrer Mutter und in der Tanjian-Halle Kampfk\xfcnste. Ihre Hingabe hat ihr herausragende Kampff\xe4higkeiten und eine mentale St\xe4rke eingebracht, die man unter Gleichaltrigen selten findet. Obwohl sie den legend\xe4ren Chi Xiao nie zu Gesicht bekommen hat, ist sie stolz auf ihre selbst entwickelte Chi-Xiao-Schwertkunst und setzt sie im Namen der Gerechtigkeit ein. \\nNachdem sie jahrelang allein mit ihrem Schwert durch Talos-II gezogen war, schloss sich Chen Qianyu auf Perlicas Einladung hin Endfield an. Ihre fr\xf6hliche Art und ihr unb\xe4ndiger Enthusiasmus treiben sie an, jede anfallende Herausforderung ohne Z\xf6gern anzugehen. \\n\\n„Man sagt, die Klinge meiner Mutter habe die Wolken selbst bewegt, Endmin. Und genau das werde ich tun … und diejenige sein, auf die du und Perlica immer z\xe4hlen k\xf6nnt!“","prof":"guard","elem":"physic","cv":{"en-us":"Rebecca Hanssen"}},{"key":"laevatain","name":"Laevatain","codename":"Laevatain","camp":"Rhodes Island","race":"Sarkaz","rarity":6,"intro":"„M\xf6ge die Abendd\xe4mmerung in Flammen aufgehen!“ \\nLaevatain ist eine Rhodes-Island-Operatorin, die auf direkte Empfehlung des Endministrators zu Endfield gekommen ist. Gem\xe4\xdf der Rahmenvereinbarung zwischen den beiden Unternehmen untersteht sie als Operatorin direkt dem Endministrator. \\nBevor sie zu Endfield Industries kam, durchstreifte Laevatain allein die Welt und war auf der Suche nach einem Lebensziel. Aufgrund dieser Reise und ihrer beeindruckenden Fertigkeiten im Einzelkampf wird sie oft als „jemand, mit der man nicht reden kann“ betrachtet. In Wahrheit ist eher das Gegenteil der Fall. Es ist blo\xdf so, dass ihre ernste, direkte Art manchmal zu br\xfcsk r\xfcberkommt und zu Missverst\xe4ndnissen f\xfchrt. \\nManchmal spricht sie auf eine Art und Weise, die andere verwirrt, und sie kommt stets auf das Thema „Erinnerung“ zur\xfcck, als ob sie absichtlich versuchen w\xfcrde, sich davon zu distanzieren, was sie ist. \\nFlammen sind zwar ihr Element, doch sie sehnt sich ebenso sehr nach Eiscreme. Dieser Widerspruch erscheint ihr vielleicht ganz nat\xfcrlich. \\n\\n„Wenn dir immer noch kalt ist, komm n\xe4her zu mir.“","prof":"assault","elem":"fire","cv":{"en-us":"Kira Buckland"}},{"key":"yvonne","name":"Yvonne","codename":"Yvonne","camp":"Endfield Industries","race":"Vouivre","rarity":6,"intro":"„Dieses Handfeuerwaffen-Paar f\xfchlt sich genau richtig an. Hm … Ich habe einige Verbesserungsm\xf6glichkeiten beim Design entdeckt. Ich werde es wohl zu einem Yvonne-Spezialmodell umbauen!“ \\nYvonne ist eine Operatorin der Spezialisierten Technikabteilung von Endfield Industries, die derzeit f\xfcr die Erforschung von \xc6ther, Verderbnis und damit in Zusammenhang stehenden Ger\xe4ten zust\xe4ndig ist. \\nAuf den ersten Blick sieht Yvonne wie die typische rebellische Modeikone aus, die ihre H\xf6rner, ihren Schweif und ihre N\xe4gel in knalligen Farben lackiert. Sie schw\xe4nzt akademische Konferenzen, um sich die neuesten Modemagazine und Pop-Alben zu besorgen. Mit ihrer Vorliebe f\xfcr alles Neue und Unkonventionelle hat Yvonne ein H\xe4ndchen daf\xfcr, Trends immer einen Schritt voraus zu sein und ihrem eigenen Rhythmus zu folgen. \\nAber niemand kann leugnen, dass sie ein wahres Genie ist. Schon w\xe4hrend ihrer Schulzeit machte sie sich mit wissenschaftlicher Forschung einen Namen, von dem andere nur tr\xe4umen konnten. Alle erwarteten von ihr, dass sie einem Spitzenforschungsinstitut beitreten und die F\xfchrung in ihrem Bereich \xfcbernehmen w\xfcrde. Stattdessen kehrte Yvonne dem Ganzen den R\xfccken und entschied sich f\xfcr Endfield. \\nUnd aus welchem Grund? Das hat sie nie erkl\xe4rt. Vielleicht kannst du sie selbst fragen. \\n\\n„Darf ich eine neue Schicht Lack auf meine Ausr\xfcstung auftragen? Die Farbe passt nicht so gut zu meinen Haaren.“","prof":"assault","elem":"ice","cv":{"en-us":"Clare Louise Connolly"}},{"key":"gilberta","name":"Gilberta","codename":"Gilberta","camp":"Rhodes Island","race":"Vulpo","rarity":6,"intro":"„Oh, hallo! Du bist in den rosigen Duft sch\xf6ner Erinnerungen geh\xfcllt … der wie ein unvollendeter Brief an einen besonderen Ort wirkt. Ich frage mich, welcher das wohl sein k\xf6nnte.“ \\nGilberta ist eine Rhodes-Island-Operatorin, die aufgrund der Rahmenvereinbarung zwischen den beiden Unternehmen zu Endfield Industries geh\xf6rt. Sie arbeitet als Botin in der Spezialisierten Technikabteilung, beherrscht eine besonders seltene Form der Originium-Techniken und kann die Schwerkraft um sich herum kontrollieren. \\nGilberta ist bei Endfield f\xfcr die Zustellung von Post und Informationen in mehreren Basen und Au\xdfenposten zust\xe4ndig. F\xfcr ihre Aufgaben muss sie oft zwischen dem Zivilisationsg\xfcrtel und dem Grenzgebiet reisen, aber sie scheint ihre Arbeit wirklich zu genie\xdfen. Seit Kurzem fragt sie sogar nach anspruchsvolleren Missionen in gef\xe4hrlichen Gebieten, um ihre Fertigkeiten zu verbessern. \\nWarfarin gab zu, dass Gilbertas fr\xf6hliche Art, gepaart mit einem Hauch von Sorgen und Hoffnungen f\xfcr die Zukunft, sie sowohl \xfcberrascht als auch ein wenig wehm\xfctig gemacht hat. \\n\\n„Hey, schau mal hier! Die fliegende Botin hat einen besonderen Brief f\xfcr dich!“","prof":"support","elem":"nature","cv":{"en-us":"Anna Devlin"}},{"key":"ardelia","name":"Ardelia","codename":"Ardelia","camp":"Rhodes Island","race":"Caprinae","rarity":6,"intro":"„Diese Welt birgt so viele Geheimnisse, die es zu entdecken gilt. Wir sollten sie besser kennenlernen … genauso wie wir mehr \xfcber uns selbst lernen sollten. Findest du nicht auch, Prof?“ \\nArdelia ist eine Rhodes-Island-Operatorin f\xfcr Endfield Industries, wo sie gem\xe4\xdf dem Rahmenvereinbarung zwischen den beiden Unternehmen als Geologin t\xe4tig ist. \\nZu Beginn ihrer Arbeit besch\xe4ftigte sich Ardelia mit Vulkanen, aber heute erforscht sie auch die \xc6therside und geologische Katastrophen. Sie verbringt die meiste Zeit im Freien und wagt sich allein an Schaupl\xe4tze von Katastrophen, um Proben zu sammeln, Geb\xe4ude zu analysieren und Theorien zu entwickeln, die zu den Eckpfeilern von Endfields Verderbnis-Bek\xe4mpfungsma\xdfnahmen geworden sind. \\nSie ist stets bescheiden und h\xf6flich, aber sie besitzt eine innere St\xe4rke, die nie zu versiegen scheint. F\xfcr sie hat Gl\xfcck eine simple Definition: einen weiteren Berg besteigen, einen neuen Weg gehen, die Stimmen der Welt h\xf6ren und die verborgenen Wunder dieses Planeten entdecken. \\nUnd wenn es dir gelingt, dich mit Ardelia anzufreunden, wird dich auch Herr Dolly m\xf6gen. \\n\\n„Herr Dolly? Lauf nicht weg! Komm und sag dem Professor hallo.“","prof":"support","elem":"nature","cv":{"en-us":"Lindsay Sheppard"}},{"key":"ember","name":"Ember","codename":"Ember","camp":"Orden des Stahlschwurs","race":"Sankta","rarity":6,"intro":"„Auf geht’s. Der Krieg h\xf6rt nie auf. Wir k\xf6nnen nur weitermachen.“ \\nEmber dient im Orden des Stahlschwurs, einer Milit\xe4reinheit, die das ganze Jahr \xfcber in den zerkl\xfcfteten n\xf6rdlichen Regionen stationiert ist. Um Nachfolger f\xfcr gefallene Kameraden zu rekrutieren, kehrte sie in den Zivilisationsg\xfcrtel zur\xfcck und nahm ein Angebot auf eine Stelle bei Endfield Industries an. \\nEmber ist die Elite des Sturmbanners im Orden des Stahlschwurs und verf\xfcgt \xfcber makellose Kampff\xe4higkeiten. Sie f\xfchrt jeden Angriff an und durchbricht mit ihren Kameraden die feindlichen Linien wie ein unzerbrechlicher Speer. F\xfcr ihre Feinde ist sie eine un\xfcberwindbare H\xfcrde. F\xfcr ihre Verb\xfcndeten ist sie eine unersch\xfctterliche Mauer. Der Orden mag sich auf Festungen und Schlachtschiffe st\xfctzen, doch Kriegerinnen wie Ember sind sein wahres R\xfcckgrat. \\n\\n„Unter der Aurora befinden sich die Verteidigungslinien der Eidw\xe4chter.“","prof":"shielder","elem":"fire","cv":{"en-us":"Rhiannon Moushall"}},{"key":"lastrite","name":"Last Rite","codename":"Last Rite","camp":"Seš’qa","race":"Sarkaz","rarity":6,"intro":"„Ich bin die … irgendwas des Krieges, nehme ich an?“ \\nBevor die Sarkaz der schwebenden Stadt sie fanden, war Last Rite ein gutm\xfctiges M\xe4dchen, das von einem Caprinae-Grabw\xe4chterpaar adoptiert worden war. Von deren Lehren gepr\xe4gt, weigerte sich die junge Nachzehrerin, die Toten zu st\xf6ren und widerstand ihrem Nahrungsaufnahme-Instinkt. Doch diese Zur\xfcckhaltung schw\xe4chte sie vor lauter Hunger, und aufgrund ihrer Unsicherheit nahm sie von anderen Abstand. \\nEine zuf\xe4llige Begegnung er\xf6ffnete Seš’qa das Potenzial von Last Rite. Das Versprechen einer „gut bezahlten Aushilfsarbeit“ und eines „Trainings zur Unterdr\xfcckung der Instinkte“ lockte sie und sie machte sich unter den H\xe4ndlern als „Prinzessin des Kampfgerichts“ einen Namen. Jetzt tr\xe4gt sie den Prototyp eines Zauberstunde-Kampfanzugs und setzt sich mit Eis und Stahl f\xfcr Endfield ein – sowohl um ihren Vertrag zu erf\xfcllen als auch um eine friedliche Zukunft anzustreben, die Endfield f\xfcr sie vorgesehen hat. \\n\\n„Wenn mein Vertrag mit Seš’qa ausl\xe4uft, kannst du mich kontaktieren … O-oh nein! Das h\xe4tte ich nicht sagen sollen! Bitte … Sag niemandem davon …“","prof":"assault","elem":"ice","cv":{"en-us":"Amber Hood"}},{"key":"lifeng","name":"Lifeng","codename":"Lifeng","camp":"Hongshan-Akademie der Wissenschaften","race":"Anasa","rarity":6,"intro":"„Ich bin nach Endfield gekommen, um etwas zu lernen. Aber … Es ist einfach zu viel auf einmal. Ich muss noch mehr Gas geben!“ \\nLifeng wurde in Wuling City geboren und macht jetzt ein Praktikum in der Spezialisierten Technikabteilung von Endfield Industries. \\nIn Wuling ist Lifeng als H\xe4uptling der Kinder bekannt und beliebt. Die jahrelange Anleitung durch Da Pan hat seine Fertigkeiten im Speerkampf geschult und ihn f\xfcr sein Streben nach Gerechtigkeit gewappnet. Nur wenige w\xfcrden in seinem fr\xf6hlichen Auftreten den Schatten erahnen, der auf ihm lastet – ein Unfall, der seine einst gl\xfcckliche Familie zerst\xf6rte und ihn einen Arm kostete. Doch die Entbehrungen haben sein Feuer nicht geschw\xe4cht. Mit Aufrichtigkeit und Leidenschaft w\xe4chst er weiter und sehnt sich nach dem Tag, an dem er gr\xf6\xdfere Verantwortung \xfcbernehmen kann. Eines Tages wird er auf eigenen F\xfc\xdfen stehen und zur\xfcckkehren, um das Zuhause zu sch\xfctzen, das auf ihn wartet. \\n\\n„Eines Tages werde ich stark genug sein, um selbst die schwierigsten Missionen zu \xfcbernehmen. Freu dich schon mal auf diesen Tag, Endmin.“","prof":"guard","elem":"physic","cv":{"en-us":"Yung-I Chang"}},{"key":"pogranichnik","name":"Pogranichnik","codename":"Pogranichnik","camp":"Rhodes Island","race":"Liberi","rarity":6,"intro":"„Die Situation ist ernst. Ich bitte respektvoll darum, schnellstm\xf6glich in den Schlachtplan eingeweiht zu werden.“ \\nPogranichnik ist ein Rhodes-Island-Operator, der f\xfcr Endfield Industries arbeitet, wo er als milit\xe4rischer Berater in der Rahmenvereinbarung zwischen den beiden Unternehmen t\xe4tig ist. \\nDank seiner fundierten Kenntnisse der Milit\xe4rtheorie und seiner hart erk\xe4mpften Erfahrung im Teamkampf lenkt Pogranichnik seine Einheit auch durch die unerwartetsten Krisen. Als ehemaliger Kommandant des Banners der Schildw\xe4chter im Orden des Stahlschwurs galten er und seine Truppen als die zuverl\xe4ssigsten Kontrahenten der Aggeloi an der Front. Als die Situation auf Talos-II jedoch immer komplexer wurde, schloss er sich ohne zu z\xf6gern Endfield Industries an. \\nEr ist fest davon \xfcberzeugt, dass der Endministrator Talos-II auf einen neuen Weg f\xfchren wird, so wie er es sich einst vorgestellt hatte. \\n\\n„Endmin, ich bin sicher, dass deine Taten diesen Kreislauf aus Krieg und Opfer endg\xfcltig durchbrechen werden.“","prof":"vanguard","elem":"physic","cv":{"en-us":"Sergey Ponomaryov"}},{"key":"alesh","name":"Alesh","codename":"Alesh","camp":"Gewerkschaftsbund von Talos-II","race":"Anaty","rarity":5,"intro":"„Beim Angeln kann man einen Wurfk\xf6der immer wieder einholen. Aber im echten Leben gibt es keinen einfachen Ausweg, wenn man erst einmal in Schwierigkeiten steckt.“ \\nAlesh wurde von einem Verbindungsmann des GBT-Sicherheitsb\xfcros vorgestellt und kam zu Endfield Industries, um Kommunikations- und Unterst\xfctzungssaufgaben im Grenzgebiet zu \xfcbernehmen. Wenn er nicht arbeitet, ist er Ausbilder f\xfcr Endfields Angelkurse. \\nEr spricht nicht gerne \xfcber seine „langweilige“ Vergangenheit. Man wei\xdf nur, dass er sich in der Unterschicht des Grenzgebiets durchgeschlagen hat und dabei immer wieder Opfer von Streit und Verrat wurde. Am Ende lie\xdf er die Stra\xdfen mit einem erblindeten Auge und einem von Ersch\xf6pfung gezeichneten K\xf6rper hinter sich. \\nAlesh ist Fl\xf6sslerverk\xe4ufer von Beruf und verbringt seine Tage mit Angeln. Doch unter dieser entspannten Oberfl\xe4che verbergen sich scharfe Instinkte und ein sicheres Urteilsverm\xf6gen. Wenn es darauf ankommt, sind seine Augen durchbohrend wie eine Hakenspitze, und er hat genauso viele Tricks auf Lager, um mit Schwierigkeiten fertigzuwerden, wie beim Einf\xe4deln eines Fangs. Auf Missionen l\xe4chelt er ebenso l\xe4ssig und f\xe4hrt Siege ein, wo sie niemand erwartet. \\n\\n„Ein gl\xfcckliches Leben zu f\xfchren, ist ungemein wichtig. Wahre Weisheit von einem alten Knaben, Endmin.“","prof":"vanguard","elem":"ice","cv":{"en-us":"Heitor Assali"}},{"key":"arclight","name":"Arclight","codename":"Arclight","camp":"Hannabit-Zirkel","race":"Kuranta","rarity":5,"intro":"„Ich bin Ekut. Mein Rufzeichen ist Arclight. Ich bin keine ge\xfcbte Wortweberin, aber ich w\xfcnsche euch alles Gute – m\xf6get ihr wie ein ansteigender Fluss flie\xdfen, Endfielders.“ \\nArclight ist eine Liedsucherin, die auf Empfehlung von Aldertone Orisha zu Endfield Industries kam. Sie arbeitet jetzt als Feldoperatorin und technische Beraterin f\xfcr Maschinen und Fahrzeuge. \\nNiemand, der durch die Wildnis streift, entkommt dem Hunger und den Katastrophen, egal f\xfcr wie klug oder f\xe4hig derjenige sich h\xe4lt. Das Ungl\xfcck hat Arclight hart getroffen. Die Wildnis verschlang ihre gesamte Familie und lie\xdf sie als einzige \xdcberlebende zur\xfcck. Doch das Gl\xfcck war ihr auch hold, als eine Gruppe von Liedsuchern des Hannabit-Zirkels sie fand und vor dem Tod bewahrte. \\nDer Hannabit-Zirkel nahm sie auf. Dort lernte sie schnell, wie man in einer rauen Umgebung \xfcberlebt und dem Beispiel der Paragonen der Hannas folgt, um jenen zu helfen, die in Not sind. Heute streift sie durch die Wildnis, um weiteren Seelen das \xdcberleben in der unbarmherzigen Welt von Talos-II zu lehren. \\nArclight mag auf den ersten Blick kalt und schroff wirken, aber ihre minimalistische Philosophie hat sich beim \xdcberleben in der Wildnis als \xe4u\xdferst effektiv erwiesen. \\n\\n„Die Reparatur eines eisernen Rosses ist wie die Behandlung eines Zystbiests. Man muss genau zuh\xf6ren, bevor man die Behandlung durchf\xfchrt.“","prof":"vanguard","elem":"electric","cv":{"en-us":"Andrea Gatchalian"}},{"key":"avywenna","name":"Avywenna","codename":"Avywenna","camp":"Talos-II Allgemeine Handelskammer","race":"Cautus","rarity":5,"intro":"„Boten m\xfcssen viele Geheimnisse sicher zustellen, und jedes davon hat seinen Preis. Doch noch teurer als die Lieferung selbst ist … mein Schweigen zu diesen Themen.“ \\nAvywenna ist eine Bewaffnete Botin. \\nBevor sie zu Endfield Industries kam, lebte sie bei einer m\xe4chtigen Logistikfamilie in der Freien Stadt Alloycarrot. Doch das Fernweh in ihrem Blut trieb sie dazu, dieses Leben hinter sich zu lassen und ihre eigene Reise anzutreten. In den vielen Orten von Talos-II machte sie einen roten Faden aus, der diese miteinander verband – den geheimnisvollen Endministrator. \\nAvywenna gl\xe4nzt in Gesellschaft und meistert alle Arten von Beziehungen voller Reife und Professionalit\xe4t. Ob sie wirklich so gutm\xfctig ist, wie sie erscheint, muss im Gespr\xe4ch mit ihr selbst er\xf6rtert werden. \\n\\n„Niemand mag Unversch\xe4mtheiten … wenn wir die Dinge also ausdiskutieren k\xf6nnen, ist mir das viel lieber, als handgreiflich zu werden. Aber nur damit wir uns verstehen: Auch ich kann Unversch\xe4mtheiten nicht gut vertragen.“","prof":"assault","elem":"electric","cv":{"en-us":"Sheena May"}},{"key":"dapan","name":"Da Pan","codename":"Da Pan","camp":"Hongshan-Akademie der Wissenschaften","race":"Ursus","rarity":5,"intro":"„Wenn dir ein Gericht nicht so gut gelingt, dann bereite es einfach \xf6fter zu! Ich koche nicht, um anzugeben, sondern um ein sch\xf6nes und fr\xf6hliches Festmahl zu zaubern!“ \\nDa Pan war auf der prestigetr\xe4chtigen Hongshan-Akademie der Wissenschaften, aber nachdem er sie verlassen hatte, \xfcbernahm er allerlei „zerstreute wichtige logistische Unterst\xfctzungsfunktionen“ – vom Koch und Elektriker bis hin zum Chauffeur und Stra\xdfenh\xe4ndler. Sein letzter Schritt? Er arbeitet unabh\xe4ngig in der Spezialisierten Technikabteilung von Endfield Industries. \\nVon allen Rollen, die er \xfcbernommen hat, erf\xfcllt ihn jene als reisender Koch mit dem gr\xf6\xdften Stolz. Er liebt es, neue Rezepte zu erkunden und originelle Gerichte zu kreieren. Nichts macht ihn gl\xfccklicher, als k\xf6stliche Mahlzeiten zuzubereiten, die ihm das h\xf6chste Lob einbringen, wenn er sie auftischt. \\nDa Pan tr\xe4gt stets eine Wasserflasche bei sich, die jedoch den wenigsten auff\xe4llt. Diejenigen, die die yanesischen Schriftzeichen lesen k\xf6nnen, werden sich vielleicht \xfcber ihre Herkunft wundern. Doch wenn sie aus Hongshan kommen, wissen sie genau, woher sie stammt und welche Bedeutung sie tr\xe4gt, denn es handelt sich um eine Ehre, die nur einem Vorhut-Wissenschaftler zuteil wird. \\n\\n„Probier mal das hier. Ich hab es selbst gekocht!“","prof":"assault","elem":"physic","cv":{"en-us":"Jon Xu"}},{"key":"snowshine","name":"Snowshine","codename":"Snowshine","camp":"Rhodes Island","race":"Ursus","rarity":5,"intro":"„Windgeschwindigkeit okay. Sichtweite gut. Perfektes Wetter zum Snowboarden.“ \\nSnowshine ist eine Rhodes-Island-Operatorin bei Endfield Industries, wo sie aufgrund der Rahmenvereinbarung zwischen den beiden Unternehmen als Rettungsprofi f\xfcr das Rettungsteam t\xe4tig ist. \\nAus bekannten Gr\xfcnden sind die echten Polarregionen von Talos-II f\xfcr die Menschheit weiterhin tabu. Da sich die Grenzen jedoch immer weiter ausdehnen, werden Fachleute wie Snowshine, die auf die Geografie der Polar- und Hochgebirgsregionen spezialisiert sind, im Zivilisationsg\xfcrtel immer gefragter. \\nAufgrund des gro\xdfen Mangels an Mitarbeitern haben Snowshine und ihr Rettungsteam immer einen vollen Terminkalender, und das selbst an Tagen, an denen keine Sondermissionen anstehen. \\nTrotz ihres vollen Kalenders hat sie es geschafft, in ihrer Freizeit ein Buch mit dem Titel „Leitfaden zum polaren \xdcberleben“ zu schreiben. Das Buch ist inzwischen zu einem wichtigen Nachschlagewerk f\xfcr \xdcberlebens- und Rettungsaktionen in der rauen, verschneiten Umgebung von Talos-II geworden. \\n\\n„Ich mag Schnee, die wei\xdfen Berggipfel und die schimmernde Sch\xf6nheit, die sich nur in der eisigen K\xe4lte offenbart … Deshalb m\xf6chte ich nicht, dass er den Leuten, die ihn ber\xfchren, schmerzhafte Erinnerungen hinterl\xe4sst.“","prof":"shielder","elem":"ice","cv":{"en-us":"Stephanie Southerland"}},{"key":"wulfgard","name":"Wulfgard","codename":"Wulfgard","camp":"Endfield Industries","race":"Lupo","rarity":5,"intro":"„Ich wei\xdf, dass St\xe4rke nicht alles ist, aber auf Talos-II gibt es ohne St\xe4rke kein \xdcberleben.“ \\nCatello Wulfgard Luppino ist ein junger S\xf6ldner, der am Rande des Zivilisationsg\xfcrtels lebt und jetzt im Krisenteam von Endfield Industries dient.\\nTrotz seines jugendlichen Alters ist Wulfgard bereits bestens mit der wankelm\xfctigen Natur der Menschheit vertraut. Aber diese Erfahrungen haben ihn nicht gebrochen, sondern ihm eine f\xfcr sein Alter ungew\xf6hnliche Reife verliehen. Ihm liegt nichts an Konflikten und im Zweifelsfall geht er einer direkten Konfrontation lieber aus dem Weg. Au\xdferdem zeigt er Geschick in der Tarnung und im Aufkl\xe4rungskampfeinsatz. Zur Erf\xfcllung seiner Mission kann der S\xf6ldner sogar gemeinsam mit seinen Feinden reisen und ihnen einen t\xf6dlichen Schlag versetzen, wenn sie es am wenigsten erwarten. \\nAls Mitglied des Landbrecher-Klans, der als das Rudel bekannt ist, kann Wulfgard ein zuverl\xe4ssiger und vertrauensw\xfcrdiger Freund sein, wenn es gelingt, sein Vertrauen zu gewinnen. Dies ist jedoch kein leichtes Unterfangen. \\n\\n„Unrealistischer Idealismus zerst\xf6rt mehr Leben, als er rettet.“","prof":"caster","elem":"fire","cv":{"en-us":"Jacopo Calatroni"}},{"key":"xaihi","name":"Xaihi","codename":"Xaihi","camp":"Orden der Stille","race":"Sarkaz","rarity":5,"intro":"„Sobald wir verbunden sind, wird Weisheit entstehen.“ \\nXaihi geh\xf6rt dem Orden der Stille an, einem Forschungsorden, der von Lateran nach Talos-II entsandt wurde, um technische Studien durchzuf\xfchren. Als eine der Versammelten glaubt sie, dass Berechnungen und Sprachanalysen den Weg nach Veritas ebnen. \\nSie kann besser mit Maschinen umgehen als mit Menschen. Ihr Talent f\xfcr Informationstechnologie ist unbestreitbar – sogar f\xfcr die \xc4btissin des Gro\xdfen Klosters im Orden der Stille. Obwohl ihre „unbefugte“ Verbesserung der Kuppel der Kathedralis eine Kaskade von Unf\xe4llen ausl\xf6ste, empfahl die \xc4btissin sie aufrichtig an Endfield Industries, in der Hoffnung, dass sie dort eine B\xfchne finden w\xfcrde, die ihrer Genialit\xe4t w\xfcrdig ist. \\nXaihi arbeitet jetzt an Bord der Dijiang an informationstechnischen Aufgaben, darunter dem Aufbau des Protorig-Netzwerks und der Systemintegration. Ihre einzigartigen Kenntnisse des Originium-Netzwerks und ihr umfassendes Wissen, das sie aus dem Orden mitbringt, machen sie zu einem unverzichtbaren Mitglied von Endfield. \\n\\n„O Wissen, f\xfchre uns nicht in Versuchung, sondern erl\xf6se uns von den Regeln der Bosheit … Ich bin Xaihi, Endministrator. M\xf6ge das Licht dich erleuchten.“","prof":"support","elem":"ice","cv":{"en-us":"Elsie Lovelock"}},{"key":"akekuri","name":"Akekuri","codename":"Akekuri","camp":"Endfield Industries","race":"Perro","rarity":4,"intro":"„Akekuri, Team Z7, melde mich zum Dienst! Freue mich, bei der Mission dabei zu sein. Machen wir sie zu einem Erfolg!“ \\nAkekuri, Hauptfrau des Einsatzteams Z7 der Spezialisierten Technikabteilung, ist bekannt f\xfcr ihr L\xe4cheln und ihr Markenzeichen – den Satz: „\xdcberlass das mir.“ Von der Missionsplanung bis zum Tagesmanagement – sie k\xfcmmert sich um alles. Neben taktischem Kommando und Strategie ist sie eine Meisterin der Koordination und findet auch mit begrenzten Ressourcen immer die optimale L\xf6sung. Sie versteht es auch, sich um ihr Team zu k\xfcmmern, sodass alle harmonisch zusammenarbeiten und bei den Aufgaben gl\xe4nzen k\xf6nnen, die ihnen am besten liegen. \\nSie hat das Einsatzteam Z7 praktisch von Grund auf neu aufgebaut. In nur wenigen Monaten hat sie sich um alles gek\xfcmmert, von der Rekrutierung \xfcber die Ausbildung bis hin zur vollst\xe4ndigen Entsendung, und das Team zu bemerkenswerten Ergebnissen gef\xfchrt. Und dabei war sie vor nicht allzu langer Zeit nur eine Studentin der Wirtschaftsschule, die sich freiwillig bei Endfield vorgestellt hat. Niemand hatte erwartet, dass ein Neuling so schnell aufsteigen und zur Hauptfrau werden w\xfcrde, der man wirklich vertrauen kann. \\nWenn du dich jemals \xfcber ihre Leidenschaft, ihren Antrieb und ihren Idealismus gewundert hast, oder \xfcber den einfachen Wunsch, der sie antreibt, dann … \\n\\n„Kaffeepause, Endmin? Ich kann dir eine Tasse einschenken!“","prof":"vanguard","elem":"fire","cv":{"en-us":"Shu Uchida"}},{"key":"antal","name":"Antal","codename":"Antal","camp":"Endfield Industries","race":"Savra","rarity":4,"intro":"„Eine Mission f\xfcr mich? Gut. Ich bin gerade auf der Suche nach M\xf6glichkeiten zum Testen modifizierter Pers\xf6nlicher Barrieren-Orbiter.“ \\nAntal ist Mitglied des Einsatzteams Z7 in Endfield und arbeitet als Unterst\xfctzer und Berater f\xfcr Originium-Technologie. Er ist clever und besitzt eine schnelle Auffassungsgabe, aber er ist nicht gerade ein Menschenkenner. Mehr als einmal hat er Kommentare abgegeben, die so deplatziert waren, dass der Rest des Teams aufst\xf6hnen musste. Trotzdem ist sein Talent f\xfcr Originium-Techniken bemerkenswert, auch wenn er sich dessen selbst kaum bewusst zu sein scheint. \\nSeine Gro\xdfmutter hatte gro\xdfen Einfluss auf ihn und so schert sich Antal wenig um konventionellen Erfolg, sondern widmet seine ganze Aufmerksamkeit dem, was ihn tats\xe4chlich fasziniert. Sei es ein Originium-Ger\xe4t, das er noch nie gesehen hat, oder ein trockener Witz, der ihn in Staunen versetzt – bis er das Gef\xfchl hat, die Geheimnisse entschl\xfcsselt zu haben, ruht der junge Savra tagelang nicht. \\n\\n„Seltsamerweise verst\xe4rkt deine Anwesenheit meinen Eifer, mein umfangreiches Wissen zu teilen, enorm.“","prof":"support","elem":"electric","cv":{"en-us":"Jacob Craner"}},{"key":"catcher","name":"Catcher","codename":"Catcher","camp":"Endfield Industries","race":"Perro","rarity":4,"intro":"„Brauchst du Deckung? Die bekommst du von mir.“ \\nCatcher geh\xf6rt zum Einsatzteam Z7 in Endfield und ist f\xfcr R\xfcckendeckung und logistische Unterst\xfctzung zust\xe4ndig. Dank seiner umfassenden milit\xe4rischen Ausbildung kann er sein umfangreiches Wissen nutzen, um seine Teamkollegen in kritischen Momenten zu unterst\xfctzen. Er wurde in eine Milit\xe4rfamilie in der Talos-II Allgemeinen Handelskammer hineingeboren und wuchs mit der Liebe hingebungsvoller Eltern und \xe4lterer Geschwister auf. Der durch einen Unfall in der Kindheit verursachte Schmerz und die Krankheit haben ihn nie untergekriegt. Stattdessen formten sie ihn zu dem unersch\xfctterlichen Krieger, der er heute ist. \\nObwohl Catcher der J\xfcngste im Team ist, \xfcbertrifft seine Reife die seiner Altersgenossen bei Weitem. Er arbeitet problemlos mit allen zusammen, springt ein, wenn ein Teamkollege Probleme hat, und bereitet sogar eine Camp-Mahlzeit zu, die auf die Bed\xfcrfnisse aller zugeschnitten ist. Wenn er in der N\xe4he ist, f\xfchlt sich das Team stets sicher und wohl. \\n\\n„Ich habe mir vor Kurzem alle Vorschl\xe4ge angesehen und mein Rezept f\xfcr Wildnis-Eintopf verbessert … Probiere ihn ruhig mal, wenn du neugierig bist, Endmin.“","prof":"shielder","elem":"physic","cv":{"en-us":"Kevin Andrew Rivera"}},{"key":"estella","name":"Estella","codename":"Estella","camp":"Endfield Industries","race":"Felin","rarity":4,"intro":"„Hm … Es f\xfchlt sich an, als w\xfcrde das Gewicht der ganzen Welt auf mir lasten … Vor allem auf meinen Knien …“ \\nEstella geh\xf6rt zum Einsatzteam Z7 in Endfield und ist f\xfcr die Informationsbeschaffung und die Kommunikation zust\xe4ndig. Da sie k\xf6rperlich schwach ist und das Ungl\xfcck sie \xfcberallhin begleitet, schreckt sie Au\xdfenstehende manchmal mit ihrer scharfen Zunge und ihrem schwarzen Humor ab. Sie hegt einen einfachen Traum: ein friedliches Leben zu f\xfchren. Schlie\xdflich hat sie schon zu viele Menschen gesehen, die wie sie selbst in einer Welt ohne Wahlm\xf6glichkeiten, ohne Ver\xe4nderung und ohne Zukunft gefangen sind. \\nEin Leben voller Gefahren und Extreme hat ihre Sinne f\xfcr die Welt abgestumpft und ihre Reizschwelle erh\xf6ht. Deshalb sucht sie manchmal nach h\xe4rteren Formen der Herausforderung – so zum Beispiel den h\xe4mmernden Rausch von Heavy-Metal-Musik. Diese seltenen Ersch\xfctterungen geben ihr ein fl\xfcchtiges Gef\xfchl von Ver\xe4nderung und von etwas Realem. \\nDurch ihre Arbeit in Endfield hofft Estella, die Welt ein bisschen besser zu machen und das Leben der Menschen in ihrer Umgebung ein bisschen einfacher zu gestalten. \\n\\n„Ich habe mich wieder einmal total verausgabt. Argh … Ich genie\xdfe lieber die Pause, ehe sie wieder vorbei ist.“","prof":"guard","elem":"ice","cv":{"en-us":"Risa Mei"}},{"key":"fluorite","name":"Fluorite","codename":"Fluorite","camp":"Endfield Industries","race":"Phidia","rarity":4,"intro":"„Sie ablenken? Sie au\xdfer Gefecht setzen? Oder … Einfach vernichten?“ \\nAls Mitglied des Einsatzteams Z7 in Endfield ist Fluorite daf\xfcr verantwortlich, die feindlichen Linien auszukundschaften und zu st\xf6ren. Sie kennt sich auf der Stra\xdfe aus, beherrscht schmutzige Tricks ebenso gut wie ihre Scharfsch\xfctzenk\xfcnste und bewahrt das Team so vor unz\xe4hligen Problemen. Sie stammt aus dem Grenzgebiet am Rande des Zivilisationsg\xfcrtels und hat durch st\xe4ndiges Umherziehen und Wandern ihren Blick gesch\xe4rft. Meistens sitzt sie mit einem leichten L\xe4cheln in der Ecke und hinterl\xe4sst bei den anderen das beunruhigende Gef\xfchl, dass ihr bereits alle Fehler aufgefallen sind. \\nDoch man sollte sie nicht f\xfcr eine Empathin halten. Fluorites Talent, Menschen zu lesen, verleiht ihr zwar au\xdfergew\xf6hnliche Instinkte auf dem Schlachtfeld, doch sie ist auch gef\xe4hrlich gut darin, Menschen mit wenigen Worten aufzuwiegeln. Das macht sie zur unberechenbarsten Quelle f\xfcr \xc4rger im Team. \\n\\n„Hast du etwas zu sagen? Nein? Dann lassen wir es f\xfcr heute gut sein, okay?“","prof":"caster","elem":"nature","cv":{"en-us":"Katiana Sarkissian"}}]'),h={SansMedium:'\n        url("'.concat(n(10414),'") format("woff2"),\n        url("').concat(n(84726),'") format("woff"),\n        url("').concat(n(20544),'") format("truetype"),\n    '),SansBold:'\n        url("'.concat(n(74738),'") format("woff2"),\n        url("').concat(n(33922),'") format("woff"),\n        url("').concat(n(29804),'") format("truetype"),\n    '),SansBlack:'\n        url("'.concat(n(30610),'") format("woff2"),\n        url("').concat(n(33058),'") format("woff"),\n        url("').concat(n(7404),'") format("truetype"),\n    '),SansRegular:'\n        url("'.concat(n(89095),'") format("woff2"),\n        url("').concat(n(90149),'") format("woff"),\n        url("').concat(n(2085),'") format("truetype"),\n    ')},p=JSON.parse('{"aic.items.0.description":"Der leistungsstarke Automatisierte Industriekomplex (AIK) von Endfield Industries erm\xf6glicht die effiziente automatisierte Produktion von verschiedenen Ausr\xfcstungen, Sprengstoffen, Batterien, taktischen Gegenst\xe4nden und anderen Materialien.","aic.items.0.title":"Automatisierte Produktion","aic.items.1.description":"Der Protokoll-Automationskern (PAK) ist eine der wichtigsten technologischen Errungenschaften von Endfield. Mithilfe des Tele-Protokolls kann der PAK eine Vielzahl von Anlagen „drucken“ und die AIK-Technologien in jeden Winkel von Talos-II bringen.","aic.items.1.title":"Protokoll-Automationskern","aic.items.2.description":"Endfield Industries setzt leistungsstarke Logistikeinheiten wie Transportb\xe4nder, Teiler und Depot-Busse ein. Diese sind f\xfcr den schnellen Aufbau automatisierter Produktionslinien unerl\xe4sslich.","aic.items.2.title":"Logistik-System","aic.items.3.description":"Endfield Industries nutzt Energieverteiler und Strommasten, um den Strom vom PAK an die angeschlossenen Anlagen zu verteilen. So wird der Stromfluss und der Betrieb der Anlagen f\xfcr die automatisierte Produktion aufrechterhalten.","aic.items.3.title":"Energiesystem","aic.items.4.description":"Die AIK-Fabrik in Wuling f\xfchrt neue Anlagen zum Sammeln und Verarbeiten verschiedener Fl\xfcssigkeiten ein, die die Massenproduktion eines bemerkenswerten Materials namens Xiranit erm\xf6glichen. Sobald sie platziert sind, werden die von der Hongshan-Akademie der Wissenschaften entwickelten Xiranit-Verteiler und Xiranit-Masten automatisch an das bestehende Stromnetz angeschlossen und versorgen die nahe gelegenen Anlagen mit Strom.","aic.items.4.title":"Wuling-AIK-Plan","common.back":"Zur\xfcck","common.latest":"Neueste","common.selectLanguage":"Sprache ausw\xe4hlen","gameplay.items.0.description":"Wage dich in die gewaltigen Gebirgsz\xfcge und verschlungenen Fl\xfcsse von Talos-II. Beseitige die Verderbnis und neutralisiere die Ankhor-Bedrohung. Leite Endfield Industries bei der Expansion \xfcber den Planeten, baue unterwegs jede Region auf und entwickle sie weiter.","gameplay.items.0.title":"Erkunde Talos-II","gameplay.items.1.description":"F\xfchre dein Team in den Kampf, arbeitet zusammen und setzt Kombofertigkeiten ein, um alle Arten von Gegnern zu besiegen. Besch\xfctzt gemeinsam das Heimatland von Talos-II.","gameplay.items.1.title":"Teamkampf","gameplay.items.2.description":"Nutze verschiedene Endfield-Anlagen, um automatisierte Produktionslinien zu erschaffen. Halte dich an die Baupl\xe4ne oder lass deiner Fantasie freien Lauf, um von Ausr\xfcstung und Sprengstoff bis hin zu Nahrung und Medikamenten alles zu produzieren, was die laufende Erweiterung unterst\xfctzt.","gameplay.items.2.title":"Baue die AIK-Fabrik","gameplay.items.3.description":"Sorge daf\xfcr, dass das Hauptquartier von Endfield Industries reibungslos arbeitet. Baue und verbessere verschiedene Kabinen, interagiere mit den Operatoren, um Vertrauen aufzubauen, pr\xe4sentiere deine Erfolge am Empfang, und empfange G\xe4ste oder besuche andere.","gameplay.items.3.title":"Verwalte Endfield Industries","header.charge":"Aufladezentrum","header.creator":"Urheber","header.login":"Anmelden","header.mute.off":"Sound: An","header.mute.on":"Sound: Aus","header.user":"Account","home.activity":"Voll aufgeladen!","home.actPreGacha":"Vorabziehung","home.download":"Download","home.fillQuestionnaire":"Beta Sign-Up","home.questionnaireDisabled":"Umfrage \xfcbermittelt","home.reserve":"Vorregistrierung","home.themeSite":"Designgalerie","home.title":"Der erste Hauch \\ndes Fr\xfchlings","home.title.v1d4":"Heimkehr","home.title1.v1d4":"Kernkapitel-Version","home.title2.v1d4":"Wuling-Showdown","home.title3.v1d4":"Wieder vereint, hinein in ein neues Kapitel","information.cate.CHARACTER":"Charakter-Pr\xe4sentation","information.cate.SPECIAL":"Spezial-Trailer","information.cate.VERSION":"Versions-Trailer","information.displayTimeFormat":"DD.MM.YYYY","information.more":"Weitere Videos","landing.downloadNow":"Jetzt herunterladen","landing.frontInfo":"OVER THE FRONTIER / INTO THE FRONT","landing.gameDesc":"3D即时策略RPG游戏","landing.welcome":"Neue Version im Anmarsch","lore.models.anchor.codename":"ANKHOR","lore.models.anchor.intro":"Ankhors sind geheimnisvolle Konstrukte, die die Bildung von Aggeloi ausl\xf6sen. Ihre Herkunft ist unbekannt und sie sind wahllos \xfcber Talos-II verstreut. Nach der Landung beginnen sie unverz\xfcglich damit, Naturmaterialien aus der Umgebung anzuziehen, um kontinuierlich Aggeloi zu erzeugen.","lore.models.anchor.name":"Ankhor","lore.models.enemy.codename":"LANDBREAKER","lore.models.enemy.intro":"Mit Landbrechern sind \xfcblicherweise Gruppen bewaffneter Pl\xfcnderer am Rande der Gesellschaft gemeint, die ihren Lebensunterhalt durch Raub oder andere Formen krimineller Gewalt verdienen. Als die Eroberungstr\xe4ume der Landbrecher zerplatzten, spaltete sich die Bande in mehrere Ableger auf. Jeder von ihnen tr\xe4gt jetzt einen anderen Namen, aber die Leute benutzen „Landbrecher“ noch immer als Sammelbegriff f\xfcr jede bewaffnete Gruppierung, die sich gegen die zivilisierte Ordnung stellt.","lore.models.enemy.name":"Landbrecher","lore.models.factory.codename":"AIC","lore.models.factory.intro":"Der Automatisierte Industriekomplex (AIK) ist eine der zentralen Technologien von Endfield Industries.  Er steht f\xfcr die erfolgreiche Miniaturisierung und Modularisierung industrieller Produktionsmaschinen. Ein kleines Team von Fachleuten kann mithilfe der AIK-Technologie schnell eine voll funktionsf\xe4hige automatisierte Produktionslinie aufbauen.","lore.models.factory.name":"Automatisierter Industriekomplex","lore.models.pile.codename":"TIANSHI PILLAR","lore.models.pile.intro":"Tianshi-S\xe4ulen sind pfeilerartige Xiranit-Ger\xe4te, die entwickelt wurden, um die Verderbnisflut einzud\xe4mmen, und z\xe4hlen zu den wichtigsten wissenschaftlichen Errungenschaften der Hongshan-Akademie der Wissenschaften. Durch die Kombination von Originium-Technologie und Feranmut-Studien entwickelten die Tianshi der HAW die Tianshi-S\xe4ule zur Bek\xe4mpfung der Verderbnisflut. Das Ger\xe4t zerstreut Xiranit-Partikel und aktiviert sie bei Bedarf, um die Auswirkungen der Verderbnis zu schw\xe4chen.","lore.models.pile.name":"Tianshi-S\xe4ule","lore.models.spaceship.codename":"DIJIANG","lore.models.spaceship.intro":"Die OMV Dijiang ist ein Raumschiff in einem k\xfcnstlichen geostation\xe4ren Orbit \xfcber Talos-II und der derzeitige Hauptsitz von Endfield Industries.  Sie wird von einem massiven Kern aus Protokoll-Originium angetrieben, und unterst\xfctzt verschiedene Subsysteme, darunter das Tele-Protokoll (TP) und den Automatisierten Industriekomplex (AIK).","lore.models.spaceship.name":"Dijiang","lore.models.trinity.codename":"AGGELOID","lore.models.trinity.intro":"Ein Aggelos (Plural: Aggeloi) bezeichnet jedes feindliche und belebte Wesen, das aus nat\xfcrlicher Materie und einer Halo-Struktur besteht und von einem Ankhor durch katalytische Konstruktion erschaffen wird. W\xe4hrend der gesamten Ausbreitung der Menschheit auf Talos-II waren die Aggeloi stets unsere gr\xf6\xdfte Bedrohung. Der Aggeloi-Krieg wurde nach dem Gegner benannt, den die Menschheit bek\xe4mpfte.","lore.models.trinity.name":"Aggelos","modal.user.currentUser":"Aktueller Account","modal.user.logout":"Abmelden","modal.user.title":"Account-Info","modal.user.userCenter":"Account-Center","nav.aic":"AIK-Fabrik-Intro","nav.calendar":"Versionskalender","nav.gameplay":"Gameplay","nav.home":"Startseite","nav.information":"Medien","nav.lore":"Hintergrundgeschichte","nav.milestone":"Vorregistrierungs-Meilensteine","nav.notice":"Neuigkeiten","nav.operator":"Operatoren","nav.preserveNow":"Jetzt vorregistrieren","nav.preserveNowShort":"Vorregistrieren","notice.detail":"Weitere Infos","notice.tab.events":"Events","notice.tab.news":"Neuigkeiten","notice.tab.notices":"Hinweise","operator.camp":"Fraktion","operator.camps.0":"Endfield Industries","operator.camps.1":"Hannabit-Zirkel","operator.camps.2":"Orden des Stahlschwurs","operator.camps.3":"Orden der Stille","operator.camps.4":"Talos-II Allgemeine Handelskammer","operator.camps.5":"Rhodes Island","operator.camps.6":"Hongshan-Akademie der Wissenschaften","operator.camps.7":"Gewerkschaftsbund von Talos-II","operator.camps.8":"Seš’qa","operator.content.akekuri.intro":"„Akekuri, Team Z7, melde mich zum Dienst! Freue mich, bei der Mission dabei zu sein. Machen wir sie zu einem Erfolg!“  Akekuri, Hauptfrau des Einsatzteams Z7 der Spezialisierten Technikabteilung, ist bekannt f\xfcr ihr L\xe4cheln und ihr Markenzeichen – den Satz: „\xdcberlass das mir.“ Von der Missionsplanung bis zum Tagesmanagement – sie k\xfcmmert sich um alles. Neben taktischem Kommando und Strategie ist sie eine Meisterin der Koordination und findet auch mit begrenzten Ressourcen immer die optimale L\xf6sung. Sie versteht es auch, sich um ihr Team zu k\xfcmmern, sodass alle harmonisch zusammenarbeiten und bei den Aufgaben gl\xe4nzen k\xf6nnen, die ihnen am besten liegen.  Sie hat das Einsatzteam Z7 praktisch von Grund auf neu aufgebaut. In nur wenigen Monaten hat sie sich um alles gek\xfcmmert, von der Rekrutierung \xfcber die Ausbildung bis hin zur vollst\xe4ndigen Entsendung, und das Team zu bemerkenswerten Ergebnissen gef\xfchrt. Und dabei war sie vor nicht allzu langer Zeit nur eine Studentin der Wirtschaftsschule, die sich freiwillig bei Endfield vorgestellt hat. Niemand hatte erwartet, dass ein Neuling so schnell aufsteigen und zur Hauptfrau werden w\xfcrde, der man wirklich vertrauen kann.  Wenn du dich jemals \xfcber ihre Leidenschaft, ihren Antrieb und ihren Idealismus gewundert hast, oder \xfcber den einfachen Wunsch, der sie antreibt, dann …  \\n „Kaffeepause, Endmin? Ich kann dir eine Tasse einschenken!“","operator.content.akekuri.name":"Akekuri","operator.content.alesh.intro":"„Beim Angeln kann man einen Wurfk\xf6der immer wieder einholen. Aber im echten Leben gibt es keinen einfachen Ausweg, wenn man erst einmal in Schwierigkeiten steckt.“  Alesh wurde von einem Verbindungsmann des GBT-Sicherheitsb\xfcros vorgestellt und kam zu Endfield Industries, um Kommunikations- und Unterst\xfctzungssaufgaben im Grenzgebiet zu \xfcbernehmen. Wenn er nicht arbeitet, ist er Ausbilder f\xfcr Endfields Angelkurse.  Er spricht nicht gerne \xfcber seine „langweilige“ Vergangenheit. Man wei\xdf nur, dass er sich in der Unterschicht des Grenzgebiets durchgeschlagen hat und dabei immer wieder Opfer von Streit und Verrat wurde. Am Ende lie\xdf er die Stra\xdfen mit einem erblindeten Auge und einem von Ersch\xf6pfung gezeichneten K\xf6rper hinter sich.  Alesh ist Fl\xf6sslerverk\xe4ufer von Beruf und verbringt seine Tage mit Angeln. Doch unter dieser entspannten Oberfl\xe4che verbergen sich scharfe Instinkte und ein sicheres Urteilsverm\xf6gen. Wenn es darauf ankommt, sind seine Augen durchbohrend wie eine Hakenspitze, und er hat genauso viele Tricks auf Lager, um mit Schwierigkeiten fertigzuwerden, wie beim Einf\xe4deln eines Fangs. Auf Missionen l\xe4chelt er ebenso l\xe4ssig und f\xe4hrt Siege ein, wo sie niemand erwartet.  \\n „Ein gl\xfcckliches Leben zu f\xfchren, ist ungemein wichtig. Wahre Weisheit von einem alten Knaben, Endmin.“","operator.content.alesh.name":"Alesh","operator.content.antal.intro":"„Eine Mission f\xfcr mich? Gut. Ich bin gerade auf der Suche nach M\xf6glichkeiten zum Testen modifizierter Pers\xf6nlicher Barrieren-Orbiter.“  Antal ist Mitglied des Einsatzteams Z7 in Endfield und arbeitet als Unterst\xfctzer und Berater f\xfcr Originium-Technologie. Er ist clever und besitzt eine schnelle Auffassungsgabe, aber er ist nicht gerade ein Menschenkenner. Mehr als einmal hat er Kommentare abgegeben, die so deplatziert waren, dass der Rest des Teams aufst\xf6hnen musste. Trotzdem ist sein Talent f\xfcr Originium-Techniken bemerkenswert, auch wenn er sich dessen selbst kaum bewusst zu sein scheint.  Seine Gro\xdfmutter hatte gro\xdfen Einfluss auf ihn und so schert sich Antal wenig um konventionellen Erfolg, sondern widmet seine ganze Aufmerksamkeit dem, was ihn tats\xe4chlich fasziniert. Sei es ein Originium-Ger\xe4t, das er noch nie gesehen hat, oder ein trockener Witz, der ihn in Staunen versetzt – bis er das Gef\xfchl hat, die Geheimnisse entschl\xfcsselt zu haben, ruht der junge Savra tagelang nicht.  \\n „Seltsamerweise verst\xe4rkt deine Anwesenheit meinen Eifer, mein umfangreiches Wissen zu teilen, enorm.“","operator.content.antal.name":"Antal","operator.content.arclight.intro":"„Ich bin Ekut. Mein Rufzeichen ist Arclight. Ich bin keine ge\xfcbte Wortweberin, aber ich w\xfcnsche euch alles Gute – m\xf6get ihr wie ein ansteigender Fluss flie\xdfen, Endfielders.“  Arclight ist eine Liedsucherin, die auf Empfehlung von Aldertone Orisha zu Endfield Industries kam. Sie arbeitet jetzt als Feldoperatorin und technische Beraterin f\xfcr Maschinen und Fahrzeuge.  Niemand, der durch die Wildnis streift, entkommt dem Hunger und den Katastrophen, egal f\xfcr wie klug oder f\xe4hig derjenige sich h\xe4lt. Das Ungl\xfcck hat Arclight hart getroffen. Die Wildnis verschlang ihre gesamte Familie und lie\xdf sie als einzige \xdcberlebende zur\xfcck. Doch das Gl\xfcck war ihr auch hold, als eine Gruppe von Liedsuchern des Hannabit-Zirkels sie fand und vor dem Tod bewahrte.  Der Hannabit-Zirkel nahm sie auf. Dort lernte sie schnell, wie man in einer rauen Umgebung \xfcberlebt und dem Beispiel der Paragonen der Hannas folgt, um jenen zu helfen, die in Not sind. Heute streift sie durch die Wildnis, um weiteren Seelen das \xdcberleben in der unbarmherzigen Welt von Talos-II zu lehren.  Arclight mag auf den ersten Blick kalt und schroff wirken, aber ihre minimalistische Philosophie hat sich beim \xdcberleben in der Wildnis als \xe4u\xdferst effektiv erwiesen.  \\n „Die Reparatur eines eisernen Rosses ist wie die Behandlung eines Zystbiests. Man muss genau zuh\xf6ren, bevor man die Behandlung durchf\xfchrt.“","operator.content.arclight.name":"Arclight","operator.content.ardelia.intro":"„Diese Welt birgt so viele Geheimnisse, die es zu entdecken gilt. Wir sollten sie besser kennenlernen … genauso wie wir mehr \xfcber uns selbst lernen sollten. Findest du nicht auch, Prof?“  Ardelia ist eine Rhodes-Island-Operatorin f\xfcr Endfield Industries, wo sie gem\xe4\xdf dem Rahmenvereinbarung zwischen den beiden Unternehmen als Geologin t\xe4tig ist.  Zu Beginn ihrer Arbeit besch\xe4ftigte sich Ardelia mit Vulkanen, aber heute erforscht sie auch die \xc6therside und geologische Katastrophen. Sie verbringt die meiste Zeit im Freien und wagt sich allein an Schaupl\xe4tze von Katastrophen, um Proben zu sammeln, Geb\xe4ude zu analysieren und Theorien zu entwickeln, die zu den Eckpfeilern von Endfields Verderbnis-Bek\xe4mpfungsma\xdfnahmen geworden sind.  Sie ist stets bescheiden und h\xf6flich, aber sie besitzt eine innere St\xe4rke, die nie zu versiegen scheint. F\xfcr sie hat Gl\xfcck eine simple Definition: einen weiteren Berg besteigen, einen neuen Weg gehen, die Stimmen der Welt h\xf6ren und die verborgenen Wunder dieses Planeten entdecken.  Und wenn es dir gelingt, dich mit Ardelia anzufreunden, wird dich auch Herr Dolly m\xf6gen.  \\n „Herr Dolly? Lauf nicht weg! Komm und sag dem Professor hallo.“","operator.content.ardelia.name":"Ardelia","operator.content.avywenna.intro":"„Boten m\xfcssen viele Geheimnisse sicher zustellen, und jedes davon hat seinen Preis. Doch noch teurer als die Lieferung selbst ist … mein Schweigen zu diesen Themen.“  Avywenna ist eine Bewaffnete Botin.  Bevor sie zu Endfield Industries kam, lebte sie bei einer m\xe4chtigen Logistikfamilie in der Freien Stadt Alloycarrot. Doch das Fernweh in ihrem Blut trieb sie dazu, dieses Leben hinter sich zu lassen und ihre eigene Reise anzutreten. In den vielen Orten von Talos-II machte sie einen roten Faden aus, der diese miteinander verband – den geheimnisvollen Endministrator.  Avywenna gl\xe4nzt in Gesellschaft und meistert alle Arten von Beziehungen voller Reife und Professionalit\xe4t. Ob sie wirklich so gutm\xfctig ist, wie sie erscheint, muss im Gespr\xe4ch mit ihr selbst er\xf6rtert werden.  \\n „Niemand mag Unversch\xe4mtheiten … wenn wir die Dinge also ausdiskutieren k\xf6nnen, ist mir das viel lieber, als handgreiflich zu werden. Aber nur damit wir uns verstehen: Auch ich kann Unversch\xe4mtheiten nicht gut vertragen.“","operator.content.avywenna.name":"Avywenna","operator.content.catcher.intro":"„Brauchst du Deckung? Die bekommst du von mir.“  Catcher geh\xf6rt zum Einsatzteam Z7 in Endfield und ist f\xfcr R\xfcckendeckung und logistische Unterst\xfctzung zust\xe4ndig. Dank seiner umfassenden milit\xe4rischen Ausbildung kann er sein umfangreiches Wissen nutzen, um seine Teamkollegen in kritischen Momenten zu unterst\xfctzen. Er wurde in eine Milit\xe4rfamilie in der Talos-II Allgemeinen Handelskammer hineingeboren und wuchs mit der Liebe hingebungsvoller Eltern und \xe4lterer Geschwister auf. Der durch einen Unfall in der Kindheit verursachte Schmerz und die Krankheit haben ihn nie untergekriegt. Stattdessen formten sie ihn zu dem unersch\xfctterlichen Krieger, der er heute ist.  Obwohl Catcher der J\xfcngste im Team ist, \xfcbertrifft seine Reife die seiner Altersgenossen bei Weitem. Er arbeitet problemlos mit allen zusammen, springt ein, wenn ein Teamkollege Probleme hat, und bereitet sogar eine Camp-Mahlzeit zu, die auf die Bed\xfcrfnisse aller zugeschnitten ist. Wenn er in der N\xe4he ist, f\xfchlt sich das Team stets sicher und wohl.  \\n „Ich habe mir vor Kurzem alle Vorschl\xe4ge angesehen und mein Rezept f\xfcr Wildnis-Eintopf verbessert … Probiere ihn ruhig mal, wenn du neugierig bist, Endmin.“","operator.content.catcher.name":"Catcher","operator.content.chen.intro":"„Nun, es hat sich herausgestellt, dass ich auch noch etwas anderes als Kampfk\xfcnste gut beherrsche. Ich kann einfach nicht anders, als deine beste Operatorin zu werden.“  Chen Qianyu ist eine Operatorin bei Endfield Industries und ein Kernmitglied des Krisenteams.  Schon in jungen Jahren trainierte sie unter Anleitung ihrer Mutter und in der Tanjian-Halle Kampfk\xfcnste. Ihre Hingabe hat ihr herausragende Kampff\xe4higkeiten und eine mentale St\xe4rke eingebracht, die man unter Gleichaltrigen selten findet. Obwohl sie den legend\xe4ren Chi Xiao nie zu Gesicht bekommen hat, ist sie stolz auf ihre selbst entwickelte Chi-Xiao-Schwertkunst und setzt sie im Namen der Gerechtigkeit ein.  Nachdem sie jahrelang allein mit ihrem Schwert durch Talos-II gezogen war, schloss sich Chen Qianyu auf Perlicas Einladung hin Endfield an. Ihre fr\xf6hliche Art und ihr unb\xe4ndiger Enthusiasmus treiben sie an, jede anfallende Herausforderung ohne Z\xf6gern anzugehen.  \\n „Man sagt, die Klinge meiner Mutter habe die Wolken selbst bewegt, Endmin. Und genau das werde ich tun … und diejenige sein, auf die du und Perlica immer z\xe4hlen k\xf6nnt!“","operator.content.chen.name":"Chen Qianyu","operator.content.dapan.intro":"„Wenn dir ein Gericht nicht so gut gelingt, dann bereite es einfach \xf6fter zu! Ich koche nicht, um anzugeben, sondern um ein sch\xf6nes und fr\xf6hliches Festmahl zu zaubern!“  Da Pan war auf der prestigetr\xe4chtigen Hongshan-Akademie der Wissenschaften, aber nachdem er sie verlassen hatte, \xfcbernahm er allerlei „zerstreute wichtige logistische Unterst\xfctzungsfunktionen“ – vom Koch und Elektriker bis hin zum Chauffeur und Stra\xdfenh\xe4ndler. Sein letzter Schritt? Er arbeitet unabh\xe4ngig in der Spezialisierten Technikabteilung von Endfield Industries.  Von allen Rollen, die er \xfcbernommen hat, erf\xfcllt ihn jene als reisender Koch mit dem gr\xf6\xdften Stolz. Er liebt es, neue Rezepte zu erkunden und originelle Gerichte zu kreieren. Nichts macht ihn gl\xfccklicher, als k\xf6stliche Mahlzeiten zuzubereiten, die ihm das h\xf6chste Lob einbringen, wenn er sie auftischt.  Da Pan tr\xe4gt stets eine Wasserflasche bei sich, die jedoch den wenigsten auff\xe4llt. Diejenigen, die die yanesischen Schriftzeichen lesen k\xf6nnen, werden sich vielleicht \xfcber ihre Herkunft wundern. Doch wenn sie aus Hongshan kommen, wissen sie genau, woher sie stammt und welche Bedeutung sie tr\xe4gt, denn es handelt sich um eine Ehre, die nur einem Vorhut-Wissenschaftler zuteil wird.  \\n „Probier mal das hier. Ich hab es selbst gekocht!“","operator.content.dapan.name":"Da Pan","operator.content.ember.intro":"„Auf geht’s. Der Krieg h\xf6rt nie auf. Wir k\xf6nnen nur weitermachen.“  Ember dient im Orden des Stahlschwurs, einer Milit\xe4reinheit, die das ganze Jahr \xfcber in den zerkl\xfcfteten n\xf6rdlichen Regionen stationiert ist. Um Nachfolger f\xfcr gefallene Kameraden zu rekrutieren, kehrte sie in den Zivilisationsg\xfcrtel zur\xfcck und nahm ein Angebot auf eine Stelle bei Endfield Industries an.  Ember ist die Elite des Sturmbanners im Orden des Stahlschwurs und verf\xfcgt \xfcber makellose Kampff\xe4higkeiten. Sie f\xfchrt jeden Angriff an und durchbricht mit ihren Kameraden die feindlichen Linien wie ein unzerbrechlicher Speer. F\xfcr ihre Feinde ist sie eine un\xfcberwindbare H\xfcrde. F\xfcr ihre Verb\xfcndeten ist sie eine unersch\xfctterliche Mauer. Der Orden mag sich auf Festungen und Schlachtschiffe st\xfctzen, doch Kriegerinnen wie Ember sind sein wahres R\xfcckgrat.  \\n „Unter der Aurora befinden sich die Verteidigungslinien der Eidw\xe4chter.“","operator.content.ember.name":"Ember","operator.content.endministrator1.intro":"Der Endministrator von Endfield Industries. In der aufgezeichneten Geschichte von Talos-II \xfcbernimmt der Endministrator die Rolle eines obersten W\xe4chters. Er besch\xfctzt die Zivilisation auf diesem Planeten und bewahrt die Menschheit vor mehreren verheerenden Katastrophen. Die Taten des Endmin haben eine Vielzahl von Geschichten, Erz\xe4hlungen und sogar Ger\xfcchten hervorgebracht.  Die Identit\xe4t des Endmin ist jedoch nach wie vor schwer nachzuvollziehen und nur eine Handvoll Menschen hat die Legende pers\xf6nlich gesehen.  Andere Fraktionen innerhalb des Zivilisationsg\xfcrtels wissen zwar, dass Endfield einen ganz besonderen Trumpf in der Hand h\xe4lt, aber mehr Informationen besitzen sie nicht.  Die mysteri\xf6se Meisterung von Originium und des Protokoll-Netzwerks durch den Endministrator sowie die Notwendigkeit des Endmins, in regelm\xe4\xdfigen Abst\xe4nden einen l\xe4ngerfristigen Schlaf einzulegen, z\xe4hlt zu Endfields wichtigsten Geheimnissen.","operator.content.endministrator1.name":"Endministrator","operator.content.endministrator2.intro":"Der Endministrator von Endfield Industries. In der aufgezeichneten Geschichte von Talos-II \xfcbernimmt der Endministrator die Rolle eines obersten W\xe4chters. Er besch\xfctzt die Zivilisation auf diesem Planeten und bewahrt die Menschheit vor mehreren verheerenden Katastrophen. Die Taten des Endmin haben eine Vielzahl von Geschichten, Erz\xe4hlungen und sogar Ger\xfcchten hervorgebracht.  Die Identit\xe4t des Endmin ist jedoch nach wie vor schwer nachzuvollziehen und nur eine Handvoll Menschen hat die Legende pers\xf6nlich gesehen.  Andere Fraktionen innerhalb des Zivilisationsg\xfcrtels wissen zwar, dass Endfield einen ganz besonderen Trumpf in der Hand h\xe4lt, aber mehr Informationen besitzen sie nicht.  Die mysteri\xf6se Meisterung von Originium und des Protokoll-Netzwerks durch den Endministrator sowie die Notwendigkeit des Endmins, in regelm\xe4\xdfigen Abst\xe4nden einen l\xe4ngerfristigen Schlaf einzulegen, z\xe4hlt zu Endfields wichtigsten Geheimnissen.","operator.content.endministrator2.name":"Endministrator","operator.content.estella.intro":"„Hm … Es f\xfchlt sich an, als w\xfcrde das Gewicht der ganzen Welt auf mir lasten … Vor allem auf meinen Knien …“  Estella geh\xf6rt zum Einsatzteam Z7 in Endfield und ist f\xfcr die Informationsbeschaffung und die Kommunikation zust\xe4ndig. Da sie k\xf6rperlich schwach ist und das Ungl\xfcck sie \xfcberallhin begleitet, schreckt sie Au\xdfenstehende manchmal mit ihrer scharfen Zunge und ihrem schwarzen Humor ab. Sie hegt einen einfachen Traum: ein friedliches Leben zu f\xfchren. Schlie\xdflich hat sie schon zu viele Menschen gesehen, die wie sie selbst in einer Welt ohne Wahlm\xf6glichkeiten, ohne Ver\xe4nderung und ohne Zukunft gefangen sind.  Ein Leben voller Gefahren und Extreme hat ihre Sinne f\xfcr die Welt abgestumpft und ihre Reizschwelle erh\xf6ht. Deshalb sucht sie manchmal nach h\xe4rteren Formen der Herausforderung – so zum Beispiel den h\xe4mmernden Rausch von Heavy-Metal-Musik. Diese seltenen Ersch\xfctterungen geben ihr ein fl\xfcchtiges Gef\xfchl von Ver\xe4nderung und von etwas Realem.  Durch ihre Arbeit in Endfield hofft Estella, die Welt ein bisschen besser zu machen und das Leben der Menschen in ihrer Umgebung ein bisschen einfacher zu gestalten.  \\n „Ich habe mich wieder einmal total verausgabt. Argh … Ich genie\xdfe lieber die Pause, ehe sie wieder vorbei ist.“","operator.content.estella.name":"Estella","operator.content.fluorite.intro":"„Sie ablenken? Sie au\xdfer Gefecht setzen? Oder … Einfach vernichten?“  Als Mitglied des Einsatzteams Z7 in Endfield ist Fluorite daf\xfcr verantwortlich, die feindlichen Linien auszukundschaften und zu st\xf6ren. Sie kennt sich auf der Stra\xdfe aus, beherrscht schmutzige Tricks ebenso gut wie ihre Scharfsch\xfctzenk\xfcnste und bewahrt das Team so vor unz\xe4hligen Problemen. Sie stammt aus dem Grenzgebiet am Rande des Zivilisationsg\xfcrtels und hat durch st\xe4ndiges Umherziehen und Wandern ihren Blick gesch\xe4rft. Meistens sitzt sie mit einem leichten L\xe4cheln in der Ecke und hinterl\xe4sst bei den anderen das beunruhigende Gef\xfchl, dass ihr bereits alle Fehler aufgefallen sind.  Doch man sollte sie nicht f\xfcr eine Empathin halten. Fluorites Talent, Menschen zu lesen, verleiht ihr zwar au\xdfergew\xf6hnliche Instinkte auf dem Schlachtfeld, doch sie ist auch gef\xe4hrlich gut darin, Menschen mit wenigen Worten aufzuwiegeln. Das macht sie zur unberechenbarsten Quelle f\xfcr \xc4rger im Team.  \\n „Hast du etwas zu sagen? Nein? Dann lassen wir es f\xfcr heute gut sein, okay?“","operator.content.fluorite.name":"Fluorite","operator.content.gilberta.intro":"„Oh, hallo! Du bist in den rosigen Duft sch\xf6ner Erinnerungen geh\xfcllt … der wie ein unvollendeter Brief an einen besonderen Ort wirkt. Ich frage mich, welcher das wohl sein k\xf6nnte.“  Gilberta ist eine Rhodes-Island-Operatorin, die aufgrund der Rahmenvereinbarung zwischen den beiden Unternehmen zu Endfield Industries geh\xf6rt. Sie arbeitet als Botin in der Spezialisierten Technikabteilung, beherrscht eine besonders seltene Form der Originium-Techniken und kann die Schwerkraft um sich herum kontrollieren.  Gilberta ist bei Endfield f\xfcr die Zustellung von Post und Informationen in mehreren Basen und Au\xdfenposten zust\xe4ndig. F\xfcr ihre Aufgaben muss sie oft zwischen dem Zivilisationsg\xfcrtel und dem Grenzgebiet reisen, aber sie scheint ihre Arbeit wirklich zu genie\xdfen. Seit Kurzem fragt sie sogar nach anspruchsvolleren Missionen in gef\xe4hrlichen Gebieten, um ihre Fertigkeiten zu verbessern.  Warfarin gab zu, dass Gilbertas fr\xf6hliche Art, gepaart mit einem Hauch von Sorgen und Hoffnungen f\xfcr die Zukunft, sie sowohl \xfcberrascht als auch ein wenig wehm\xfctig gemacht hat.  \\n „Hey, schau mal hier! Die fliegende Botin hat einen besonderen Brief f\xfcr dich!“","operator.content.gilberta.name":"Gilberta","operator.content.laevatain.intro":"„M\xf6ge die Abendd\xe4mmerung in Flammen aufgehen!“  Laevatain ist eine Rhodes-Island-Operatorin, die auf direkte Empfehlung des Endministrators zu Endfield gekommen ist. Gem\xe4\xdf der Rahmenvereinbarung zwischen den beiden Unternehmen untersteht sie als Operatorin direkt dem Endministrator.  Bevor sie zu Endfield Industries kam, durchstreifte Laevatain allein die Welt und war auf der Suche nach einem Lebensziel. Aufgrund dieser Reise und ihrer beeindruckenden Fertigkeiten im Einzelkampf wird sie oft als „jemand, mit der man nicht reden kann“ betrachtet. In Wahrheit ist eher das Gegenteil der Fall. Es ist blo\xdf so, dass ihre ernste, direkte Art manchmal zu br\xfcsk r\xfcberkommt und zu Missverst\xe4ndnissen f\xfchrt.  Manchmal spricht sie auf eine Art und Weise, die andere verwirrt, und sie kommt stets auf das Thema „Erinnerung“ zur\xfcck, als ob sie absichtlich versuchen w\xfcrde, sich davon zu distanzieren, was sie ist.  Flammen sind zwar ihr Element, doch sie sehnt sich ebenso sehr nach Eiscreme. Dieser Widerspruch erscheint ihr vielleicht ganz nat\xfcrlich.  \\n „Wenn dir immer noch kalt ist, komm n\xe4her zu mir.“","operator.content.laevatain.name":"Laevatain","operator.content.lastrite.intro":"„Ich bin die … irgendwas des Krieges, nehme ich an?“  Bevor die Sarkaz der schwebenden Stadt sie fanden, war Last Rite ein gutm\xfctiges M\xe4dchen, das von einem Caprinae-Grabw\xe4chterpaar adoptiert worden war. Von deren Lehren gepr\xe4gt, weigerte sich die junge Nachzehrerin, die Toten zu st\xf6ren und widerstand ihrem Nahrungsaufnahme-Instinkt. Doch diese Zur\xfcckhaltung schw\xe4chte sie vor lauter Hunger, und aufgrund ihrer Unsicherheit nahm sie von anderen Abstand.  Eine zuf\xe4llige Begegnung er\xf6ffnete Seš’qa das Potenzial von Last Rite. Das Versprechen einer „gut bezahlten Aushilfsarbeit“ und eines „Trainings zur Unterdr\xfcckung der Instinkte“ lockte sie und sie machte sich unter den H\xe4ndlern als „Prinzessin des Kampfgerichts“ einen Namen. Jetzt tr\xe4gt sie den Prototyp eines Zauberstunde-Kampfanzugs und setzt sich mit Eis und Stahl f\xfcr Endfield ein – sowohl um ihren Vertrag zu erf\xfcllen als auch um eine friedliche Zukunft anzustreben, die Endfield f\xfcr sie vorgesehen hat.  \\n „Wenn mein Vertrag mit Seš’qa ausl\xe4uft, kannst du mich kontaktieren … O-oh nein! Das h\xe4tte ich nicht sagen sollen! Bitte … Sag niemandem davon …“","operator.content.lastrite.name":"Last Rite","operator.content.lifeng.intro":"„Ich bin nach Endfield gekommen, um etwas zu lernen. Aber … Es ist einfach zu viel auf einmal. Ich muss noch mehr Gas geben!“  Lifeng wurde in Wuling City geboren und macht jetzt ein Praktikum in der Spezialisierten Technikabteilung von Endfield Industries.  In Wuling ist Lifeng als H\xe4uptling der Kinder bekannt und beliebt. Die jahrelange Anleitung durch Da Pan hat seine Fertigkeiten im Speerkampf geschult und ihn f\xfcr sein Streben nach Gerechtigkeit gewappnet. Nur wenige w\xfcrden in seinem fr\xf6hlichen Auftreten den Schatten erahnen, der auf ihm lastet – ein Unfall, der seine einst gl\xfcckliche Familie zerst\xf6rte und ihn einen Arm kostete. Doch die Entbehrungen haben sein Feuer nicht geschw\xe4cht. Mit Aufrichtigkeit und Leidenschaft w\xe4chst er weiter und sehnt sich nach dem Tag, an dem er gr\xf6\xdfere Verantwortung \xfcbernehmen kann. Eines Tages wird er auf eigenen F\xfc\xdfen stehen und zur\xfcckkehren, um das Zuhause zu sch\xfctzen, das auf ihn wartet.  \\n „Eines Tages werde ich stark genug sein, um selbst die schwierigsten Missionen zu \xfcbernehmen. Freu dich schon mal auf diesen Tag, Endmin.“","operator.content.lifeng.name":"Lifeng","operator.content.perlica.intro":"„Wir haben einst gek\xe4mpft und nicht aufgegeben … denn wir wollen deine R\xfcckkehr erleben.“  Perlica ist die Aufseherin bei Endfield Industries und die offizielle Sprecherin des Unternehmens. In erster Linie ist sie daf\xfcr verantwortlich, die Entwicklung und Anwendung der Protokoll-Originium-Technologie zu beaufsichtigen und voranzutreiben, w\xe4hrend sie gleichzeitig den Betrieb der Dijiang verwaltet.  Als herausragende Expertin f\xfcr Techno-Protokolle hat sie die Forschung geleitet, die einen entscheidenden Einfluss auf die adaptive Entwicklung und Anwendung dieser Technologie hatte. Zudem hat sie dazu beigetragen, den Automatisierten Industriekomplex (AIK-Fabrik) zu verfeinern.  Sie ist in der Lage, auf unterschiedlichste Krisen ruhig und entschlossen zu reagieren. Allerdings steht Endfield oft vor Herausforderungen, die alle Erwartungen \xfcbersteigen. W\xe4hrend der Endministrator sich im Schlafzustand befand, \xfcbernahm sie das Kommando \xfcber das Krisenteam und f\xfchrte die Helden von Endfield Industries in einen Kampf f\xfcr eine gr\xf6\xdfere Sache. Perlica bewegt sich unerm\xfcdlich durch den Zivilisationsg\xfcrtel und tut alles in ihrer Macht Stehende, um die Ordnung aufrechtzuerhalten und die Dinge am Laufen zu halten.  \\n „Nur, wenn wir das Land durchwandern, k\xf6nnen wir jeden Atemzug und jeden Pulsschlag des Lebens sp\xfcren … genau daf\xfcr k\xe4mpft Endfield.“","operator.content.perlica.name":"Perlica","operator.content.pogranichnik.intro":"„Die Situation ist ernst. Ich bitte respektvoll darum, schnellstm\xf6glich in den Schlachtplan eingeweiht zu werden.“  Pogranichnik ist ein Rhodes-Island-Operator, der f\xfcr Endfield Industries arbeitet, wo er als milit\xe4rischer Berater in der Rahmenvereinbarung zwischen den beiden Unternehmen t\xe4tig ist.  Dank seiner fundierten Kenntnisse der Milit\xe4rtheorie und seiner hart erk\xe4mpften Erfahrung im Teamkampf lenkt Pogranichnik seine Einheit auch durch die unerwartetsten Krisen. Als ehemaliger Kommandant des Banners der Schildw\xe4chter im Orden des Stahlschwurs galten er und seine Truppen als die zuverl\xe4ssigsten Kontrahenten der Aggeloi an der Front. Als die Situation auf Talos-II jedoch immer komplexer wurde, schloss er sich ohne zu z\xf6gern Endfield Industries an.  Er ist fest davon \xfcberzeugt, dass der Endministrator Talos-II auf einen neuen Weg f\xfchren wird, so wie er es sich einst vorgestellt hatte.  \\n „Endmin, ich bin sicher, dass deine Taten diesen Kreislauf aus Krieg und Opfer endg\xfcltig durchbrechen werden.“","operator.content.pogranichnik.name":"Pogranichnik","operator.content.rossi.intro":"„Ein Kinderspiel f\xfcr jemanden wie mich!“ Rossina Wulfperl Luppino, Wulfgards j\xfcngere Schwester und die Perle des Rudels. In einer Fehde mit den Knochenbrechern zahlten viele Wolfs\xe4lteste einen blutigen Preis, um sie in Sicherheit zu bringen. An diesem Tag f\xe4rbte das Blut ihre Wickeldecke rot … Wulfgard agiert schon seit Jahren unabh\xe4ngig vom Klan, aber das Rudel brauchte einen Anf\xfchrer, und Rossi nahm diese Verantwortung auf sich. Eigentlich ist sie der Ansicht, dass ihr Bruder, der bereits in jungen Jahren Ruhm erlangte, das gesamte Rudel anf\xfchren sollte. Sie wird niemals m\xfcde, ihn nachdr\xfccklich daran zu erinnern und dazu aufzufordern. Die \xc4ltesten des Klans w\xfcrden gern sehen, wie Rossi sich mehr ihrem Alter entsprechend verh\xe4lt und mehr Zeit damit verbringt, ihren Leidenschaften nachzugehen. Rossi jedoch kann die Last der „Verantwortung“ niemals von ihrem Herzen nehmen und ist stets bem\xfcht, zum Wohle ihrer Familie und des Klans noch verl\xe4sslicher und st\xe4rker zu werden. Insgeheim sehnt Rossi sich danach, Teil einer Heldensage zu sein und tr\xe4umt davon, irgendwann an der Seite eines legend\xe4ren Helden zu k\xe4mpfen. Daf\xfcr gew\xe4hrt sie sich ab und an kleine Auszeiten. „Die Bisse waren wirklich heftig, aber das Rudel hat keine Angst vor weiteren Narben!“","operator.content.rossi.name":"Rossi","operator.content.snowshine.intro":"„Windgeschwindigkeit okay. Sichtweite gut. Perfektes Wetter zum Snowboarden.“  Snowshine ist eine Rhodes-Island-Operatorin bei Endfield Industries, wo sie aufgrund der Rahmenvereinbarung zwischen den beiden Unternehmen als Rettungsprofi f\xfcr das Rettungsteam t\xe4tig ist.  Aus bekannten Gr\xfcnden sind die echten Polarregionen von Talos-II f\xfcr die Menschheit weiterhin tabu. Da sich die Grenzen jedoch immer weiter ausdehnen, werden Fachleute wie Snowshine, die auf die Geografie der Polar- und Hochgebirgsregionen spezialisiert sind, im Zivilisationsg\xfcrtel immer gefragter.  Aufgrund des gro\xdfen Mangels an Mitarbeitern haben Snowshine und ihr Rettungsteam immer einen vollen Terminkalender, und das selbst an Tagen, an denen keine Sondermissionen anstehen.  Trotz ihres vollen Kalenders hat sie es geschafft, in ihrer Freizeit ein Buch mit dem Titel „Leitfaden zum polaren \xdcberleben“ zu schreiben. Das Buch ist inzwischen zu einem wichtigen Nachschlagewerk f\xfcr \xdcberlebens- und Rettungsaktionen in der rauen, verschneiten Umgebung von Talos-II geworden.  \\n „Ich mag Schnee, die wei\xdfen Berggipfel und die schimmernde Sch\xf6nheit, die sich nur in der eisigen K\xe4lte offenbart … Deshalb m\xf6chte ich nicht, dass er den Leuten, die ihn ber\xfchren, schmerzhafte Erinnerungen hinterl\xe4sst.“","operator.content.snowshine.name":"Snowshine","operator.content.tangtang.intro":"„Der Oberh\xe4uptling ist da! Du, du und du, ihr untersteht alle meinem Kommando!“ Tangtang ist Oberh\xe4uptling der Qingbo-Palisade. Sie ist sehr direkt, Treue ist ihr sehr wichtig und sie handelt stets frei und ungebunden aus dem Bauch heraus. Sie liebt die Freiheit und spielt gerne im Wasser, hasst es aber, verraten zu werden. Wenn sie dich einmal zu ihren Freunden z\xe4hlt, wird sie kaum eine M\xfche scheuen, um dich zu unterst\xfctzen. Als kleines Kind wurde Tangtang von einer unbekannten Person in ein Bambusk\xf6rbchen gelegt und von der Str\xf6mung des Flusses zur Qingbo-Palisade getrieben. Dort adoptierten die Palisadeure sie und machten sie zu einem Mitglied ihrer Familie. Viele sehen in ihr noch ein Kind, das man verw\xf6hnen sollte, aber tief im Inneren ist sie bereits fest entschlossen, die Last der Verantwortung f\xfcr die Zukunft der Qingbo-Palisade zu tragen. Keiner der R\xfcckschl\xe4ge, die sie erleben musste, konnte ihre Hingabe zu ihrer Welt schm\xe4lern. Tangtang hat sich Endfield Industries angeschlossen, um Antworten auf ihre Fragen zu finden und um die Entwicklung der Qingbo-Palisade vorantreiben zu k\xf6nnen. „Sorg daf\xfcr, dass sie niemals in die N\xe4he von Mi Fu kommt, sonst gibt es Sachsch\xe4den.“ Diese Warnung stammt von einem Operator aus der Logistik-Hauptabteilung. „Hast du mich nur hergerufen, um mir ein Lob auszusprechen? Na, dann leg noch eins drauf! Ich liebe es, die Wahrheit zu h\xf6ren!“","operator.content.tangtang.name":"Tangtang","operator.content.wulfgard.intro":"„Ich wei\xdf, dass St\xe4rke nicht alles ist, aber auf Talos-II gibt es ohne St\xe4rke kein \xdcberleben.“  Catello Wulfgard Luppino ist ein junger S\xf6ldner, der am Rande des Zivilisationsg\xfcrtels lebt und jetzt im Krisenteam von Endfield Industries dient. Trotz seines jugendlichen Alters ist Wulfgard bereits bestens mit der wankelm\xfctigen Natur der Menschheit vertraut. Aber diese Erfahrungen haben ihn nicht gebrochen, sondern ihm eine f\xfcr sein Alter ungew\xf6hnliche Reife verliehen. Ihm liegt nichts an Konflikten und im Zweifelsfall geht er einer direkten Konfrontation lieber aus dem Weg. Au\xdferdem zeigt er Geschick in der Tarnung und im Aufkl\xe4rungskampfeinsatz. Zur Erf\xfcllung seiner Mission kann der S\xf6ldner sogar gemeinsam mit seinen Feinden reisen und ihnen einen t\xf6dlichen Schlag versetzen, wenn sie es am wenigsten erwarten.  Als Mitglied des Landbrecher-Klans, der als das Rudel bekannt ist, kann Wulfgard ein zuverl\xe4ssiger und vertrauensw\xfcrdiger Freund sein, wenn es gelingt, sein Vertrauen zu gewinnen. Dies ist jedoch kein leichtes Unterfangen.  \\n „Unrealistischer Idealismus zerst\xf6rt mehr Leben, als er rettet.“","operator.content.wulfgard.name":"Wulfgard","operator.content.xaihi.intro":"„Sobald wir verbunden sind, wird Weisheit entstehen.“  Xaihi geh\xf6rt dem Orden der Stille an, einem Forschungsorden, der von Lateran nach Talos-II entsandt wurde, um technische Studien durchzuf\xfchren. Als eine der Versammelten glaubt sie, dass Berechnungen und Sprachanalysen den Weg nach Veritas ebnen.  Sie kann besser mit Maschinen umgehen als mit Menschen. Ihr Talent f\xfcr Informationstechnologie ist unbestreitbar – sogar f\xfcr die \xc4btissin des Gro\xdfen Klosters im Orden der Stille. Obwohl ihre „unbefugte“ Verbesserung der Kuppel der Kathedralis eine Kaskade von Unf\xe4llen ausl\xf6ste, empfahl die \xc4btissin sie aufrichtig an Endfield Industries, in der Hoffnung, dass sie dort eine B\xfchne finden w\xfcrde, die ihrer Genialit\xe4t w\xfcrdig ist.  Xaihi arbeitet jetzt an Bord der Dijiang an informationstechnischen Aufgaben, darunter dem Aufbau des Protorig-Netzwerks und der Systemintegration. Ihre einzigartigen Kenntnisse des Originium-Netzwerks und ihr umfassendes Wissen, das sie aus dem Orden mitbringt, machen sie zu einem unverzichtbaren Mitglied von Endfield.  \\n „O Wissen, f\xfchre uns nicht in Versuchung, sondern erl\xf6se uns von den Regeln der Bosheit … Ich bin Xaihi, Endministrator. M\xf6ge das Licht dich erleuchten.“","operator.content.xaihi.name":"Xaihi","operator.content.yvonne.intro":"„Dieses Handfeuerwaffen-Paar f\xfchlt sich genau richtig an. Hm … Ich habe einige Verbesserungsm\xf6glichkeiten beim Design entdeckt. Ich werde es wohl zu einem Yvonne-Spezialmodell umbauen!“  Yvonne ist eine Operatorin der Spezialisierten Technikabteilung von Endfield Industries, die derzeit f\xfcr die Erforschung von \xc6ther, Verderbnis und damit in Zusammenhang stehenden Ger\xe4ten zust\xe4ndig ist.  Auf den ersten Blick sieht Yvonne wie die typische rebellische Modeikone aus, die ihre H\xf6rner, ihren Schweif und ihre N\xe4gel in knalligen Farben lackiert. Sie schw\xe4nzt akademische Konferenzen, um sich die neuesten Modemagazine und Pop-Alben zu besorgen. Mit ihrer Vorliebe f\xfcr alles Neue und Unkonventionelle hat Yvonne ein H\xe4ndchen daf\xfcr, Trends immer einen Schritt voraus zu sein und ihrem eigenen Rhythmus zu folgen.  Aber niemand kann leugnen, dass sie ein wahres Genie ist. Schon w\xe4hrend ihrer Schulzeit machte sie sich mit wissenschaftlicher Forschung einen Namen, von dem andere nur tr\xe4umen konnten. Alle erwarteten von ihr, dass sie einem Spitzenforschungsinstitut beitreten und die F\xfchrung in ihrem Bereich \xfcbernehmen w\xfcrde. Stattdessen kehrte Yvonne dem Ganzen den R\xfccken und entschied sich f\xfcr Endfield.  Und aus welchem Grund? Das hat sie nie erkl\xe4rt. Vielleicht kannst du sie selbst fragen.  \\n „Darf ich eine neue Schicht Lack auf meine Ausr\xfcstung auftragen? Die Farbe passt nicht so gut zu meinen Haaren.“","operator.content.yvonne.name":"Yvonne","operator.detail.back":"Zur\xfcck zur Operator-Liste","operator.elem.electric":"Elektrisch","operator.elem.fire":"Hitze","operator.elem.ice":"Kryo","operator.elem.nature":"Natur","operator.elem.physic":"Physisch","operator.filter.all":"Alle","operator.filter.elem":"Element","operator.filter.prof":"Klasse","operator.more":"Alle Operatoren","operator.prof.assault":"Frontk\xe4mpfer","operator.prof.caster":"Wirker","operator.prof.guard":"W\xe4chter","operator.prof.shielder":"Verteidiger","operator.prof.support":"Unterst\xfctzer","operator.prof.vanguard":"Vorhut","operator.race":"Spezies","operator.races.0":"Unter Verschluss","operator.races.1":"Anasa","operator.races.10":"Caprinae","operator.races.11":"Cautus","operator.races.12":"Savra","operator.races.13":"Sankta","operator.races.14":"Sarkaz","operator.races.15":"Vouivre","operator.races.16":"Vulpo","operator.races.17":"Ursus","operator.races.18":"Kylin","operator.races.2":"Anaty","operator.races.3":"Phidia","operator.races.4":"Felin","operator.races.5":"Kuranta","operator.races.6":"Liberi","operator.races.7":"Lung","operator.races.8":"Lupo","operator.races.9":"Perro","reserveFooter.title":"Jetzt vorregistrieren","reserveFooter.titleReserved":"Vorregistrierung abgeschlossen","reserveFooter.titleReserved2":"Willkommen auf Talos-II","section.aic":"AIK-Fabrik-Intro","section.gameplay":"Gameplay","section.information":"Medien","section.lore":"Hintergrundgeschichte","section.milestone":"Globale Meilensteine der Vorregistrierung f\xfcr Endfield","section.notice":"Neuigkeiten","subpage.news.empty":"Noch keine Inhalte","subpage.news.title":"Neuigkeiten","subpage.video.empty":"Noch keine Inhalte","subpage.video.title":"Videos","toast.networkError":"Netzwerkfehler","operator.content.zhuangfy.name":"Zhuang Fangyi","operator.content.zhuangfy.intro":"„Wenn du nie aufgibst, verlierst du auch nie.“\\nOperatorin Zhuang Fangyi dient als Vize des Entwicklungs- und Forschungsbezirks Wuling und als leitende Tianshi f\xfcr das Projekt zur Erforschung neuartiger Materialien auf Xiranitbasis. Auf Empfehlung der HAW hat sie sich Endfield Industries angeschlossen, um den Riss zu erforschen.\\nZhuang Fangyi stammt aus Hongshan und bewies schon fr\xfch au\xdferordentliches Talent. So wurde sie bereits als Jugendliche aufgrund ihrer herausragenden akademischen Leistungen an der Akademie der Tianshi-Beh\xf6rde aufgenommen. Dank ihrer au\xdfergew\xf6hnlichen F\xe4higkeiten wurde sie sp\xe4ter f\xfcr das Xiranit-Projekt ausgew\xe4hlt und avancierte damit zum j\xfcngsten Mitglied der Wuling-Forschungsstation. Nach einer Katastrophe, bei der fast die gesamte Belegschaft der Forschungsstation verstarb, wurde sie trotz ihrer Jugend zur Vize ernannt, \xfcbernahm die F\xfchrungsverantwortung und trug die Last ganz Wulings auf ihren Schultern.\\nObwohl sie zu Krisenzeiten ins Amt berufen wurde, fasste sie schnell wieder Tritt. In nur einem Jahrzehnt erbl\xfchte nicht nur Wuling unter ihrer F\xfchrung zu einer wachsenden Metropole; auch sie selbst wuchs durch alle H\xf6hen und Tiefen zu einer engagierten und verantwortungsbewussten F\xfchrungspers\xf6nlichkeit heran. Die Katastrophe von vor einem Jahrzehnt schwebt jedoch wie eine dunkle Wolke \xfcber allem und erinnert sie stets daran, dass Frieden und Wohlstand von Wuling City jederzeit vergehen k\xf6nnten.\\n„Solange wir standhaft bleiben, ist nichts wirklich verloren.“","operator.content.camille.name":"Camille","operator.content.camille.intro":"„Aus den tiefsten Schatten wird einmal mehr ein Tropfen Blut vergossen.“ \\nCamille Arno, ein Bewahrer aus Seš’qa, der auf die Bew\xe4ltigung gewaltt\xe4tiger Vorf\xe4lle spezialisiert ist, die von den Sarkaz verursacht werden oder sich gegen sie richten. Als einer der besten Bewahrer beherrscht er die blutgebundenen Originium-Techniken und ist besonders geschickt darin, jeglicher Art von finsterer Hexerei entgegenzuwirken. \\nUm seine Heimat Seš’qa zu sch\xfctzen, hat Camille pers\xf6nlich unz\xe4hlige gef\xe4hrliche Verbrecher gefasst, doch bei der Suche nach seinem Blutsverwandten musste er immer wieder R\xfcckschl\xe4ge hinnehmen. Von vergangenen Entt\xe4uschungen gezeichnet, hat er sich daran gew\xf6hnt, sich k\xfchl und distanziert zu geben und die F\xfcrsorge anderer zu meiden – so sch\xfctzt er sich. Doch wenn es um Freunde geht, die sein Vertrauen gewonnen haben, zeigt er sich von seiner aufrichtigen und direkten Seite. \\nDerzeit bem\xfcht er sich aus pers\xf6nlichen Gr\xfcnden darum, mit Endfield Industries zusammenzuarbeiten. Er freut sich darauf, gemeinsam mit dir ferne L\xe4nder zu bereisen und eure lang gehegten W\xfcnsche zu erf\xfcllen. \\n„Leere Ehrungen z\xe4hlen jetzt nicht mehr. Mein Blut ist immer bei dir.“","operator.content.mifu.name":"Mi Fu","operator.content.mifu.intro":"„Wir sind ein kampferprobtes Team, richtig?“ \\nMi Fu, Hauptfrau der Wache von Wuling und die treue Untergebene der Vize Tianshi Zhuang Fangyi. Als mehrfache Gewinnerin des „Helden der Vorhut“-Preises von Wuling belegt sie den zweiten Platz in der Rangliste der zivilen Kampfkraft der Stadt. F\xfcr ihre Kollegen ist sie sowohl die strengste Ausbilderin als auch die f\xfcrsorglichste Vorgesetzte. Als Stammkundin am Reiskuchenstand in der Fangxing-Stra\xdfe ist sie f\xfcr Kinder eine Heldin, f\xfcr Unruhestifter ein Albtraum und f\xfcr jeden Eindringling der Schrecken. Obwohl sie von der Qingbo-Palisade als „Verr\xe4terin“ bezeichnet wird, bleibt sie die wahre Erbin der Qingbo-Kampfk\xfcnste. Als Tangtangs Kindheitsfreundin und Rivalin ist sie eine Kriegerin, die bis zum bitteren Ende gegen die Verderbnisflut gek\xe4mpft hat, ohne jemals den R\xfcckzug anzutreten … \\nWenn du Mi Fu besser kennenlernen m\xf6chtest, kannst du entweder ihre Rivalin oder ihre Freundin werden – das sind die beiden Beziehungen, die ihr am wichtigsten sind. Das Erste l\xe4sst ihr Blut in Wallung geraten; das Letztere treibt sie dazu, jeden Schlag zu landen, ohne R\xfccksicht auf ihr eigenes Leben. \\nUm sich nun bei den Freunden zu revanchieren, die an ihrer Seite gek\xe4mpft haben, und um es immer wieder mit neuen, w\xfcrdigen Gegnern aufzunehmen, hat sie ihr Austauschprogramm bei Endfield Industries begonnen. \\n„Diesmal bringe ich den Schlamassel f\xfcr dich in Ordnung.“","home.title.v1d3":"Intermezzos: Vergessene Vergangenheiten","header.goToGame":"Zum Spiel","operator.content.lizhiyan.name":"Arkan","operator.content.lizhiyan.intro":"„Ich werde die Ehre der Yinglungs hochhalten.“ \\nHauptfrau der Yinglung-Sondereinheit (YSE), Arkan. Ist seit langem am Yinglung-Pass stationiert und f\xfchrt regelm\xe4\xdfig Erkundungsauftr\xe4ge innerhalb der Sperrzone durch. Sie ist ernst, akribisch und neigt nicht schnell zum L\xe4cheln. \\nDas Desaster in der Sperrzone Nord-Wuling hat Arkan alles genommen. Seither hat sie nur noch ein Ziel vor Augen: den riesigen Wuling-Riss einzud\xe4mmen. Sie ist immer wieder weit vorgedrungen. Ihr Hass f\xfchrt sie Schritt f\xfcr Schritt in die Tiefe, h\xe4lt sie aber auch am Leben, wenn alle Hoffnung verloren scheint. \\nArkan spiegelt alle Qualit\xe4ten eines YSE-Mitglieds wider: absoluter Gehorsam, taktisches Verst\xe4ndnis, fortw\xe4hrendes Training und einen unbiegsamen Geist. Jene, die ebenso geliebte Personen bei Desastern verloren haben, erkennen sich zum Teil in Arkan wieder … \\nManche finden sie kalt, doch f\xfcr die YSE-Mitglieder ist ein gewisser Abstand auch eine Form des gegenseitigen Schutzes. \\n„Sei aus Ferrium, bewege dich wie eine scharfe Klinge. Yinglung gewinnt durch Schwung.“","operator.content.liino.name":"Liino","operator.content.liino.intro":"„Funkel, funkel! Meine neueste Vorstellung geht gleich los!“ \\nLiino ist ein Ausnahmetalent der Allgemeinen Handelskammer von Talos-II. Die \xd6ffentlichkeit liebt sie seit ihrem Deb\xfct und sie ist bekannt als „Morgenstern von La Fantoma“.Sie ist bekannt f\xfcr ihren exquisiten Gesang und ihren einzigartigen Auftrittsstil; ihre Konzerte stellen oft Normen in Frage und trotzen den Konventionen der Branche. \\nSie schafft es immer wieder, ihrem Publikum ein einzigartiges Erlebnis zu bieten, und gro\xdfe Unternehmen rei\xdfen sich stets darum, jede einzelne ihrer Shows zu sponsern. Auch wenn der kometenhafte Aufstieg dieser Sarkaz Djall nicht ganz unumstritten ist, ist jeder, der sie auf der B\xfchne sieht, hoffnungslos von ihrer Ausstrahlung fasziniert. \\nDerzeit treibt Liino die Planungen f\xfcr ihre Talos-II-Konzerttournee systematisch voran. Sie glaubt, dass sie eine Leistung zeigen wird, wie man sie noch nie gesehen hat, und dass der Tag kommen wird, an dem sie ganz oben auf der Weltb\xfchne gl\xe4nzen wird. \\n„Oh, das ist s\xfc\xdf! Wie soll ich mich nur bedanken …? Ich hab’s! Ich werde dich einfach mit Konzertkarten \xfcbersch\xfctten, bis wir quitt sind, wie w\xe4re das?“","operator.content.typhoea.name":"Typhoeus","operator.content.typhoea.intro":"„Eine gute Geschichte ist wie eine gute J\xe4gerin. Beide zielen direkt auf das Herz ab.“ \\nTyphoeus, Wildnisj\xe4gerin aus Rhodes Island, interessiert sich f\xfcr die Welt. Sie ist begierig darauf, unbewohnte und unerforschte Orte zu erkunden, um die vergessene Vergangenheit zu entdecken. \\nAuf Talos-II sind viele Legenden der Sami bereits in Vergessenheit geraten und nur noch eine Handvoll Samifjod erinnern sich an sie. Typhoeus hat sich vorgenommen, sie nacheinander zu besuchen und diese bruchst\xfcckhaften Erinnerungen in ihrem Notizbuch festzuhalten. \\nNach ihrer Ankunft in Endfield beschr\xe4nkten sich die Geschichten, denen sie nachging, nicht mehr nur auf vergessene Legenden. Sie lernte viele neue Freunde kennen und tauschte Geschichten mit Menschen aus dem ganzen Land aus. \\nUnd w\xe4hrend sie diesen Legenden nachgeht, schreibt sie auch ihre eigene Geschichte. \\nEines Tages, wenn jede Seite ihres Notizbuchs vollgeschrieben ist, wird sie zu den Freunden um sie herum verk\xfcnden: \\n„Legenden sind nie weit weg … Sie k\xf6nnen sich direkt hier bei uns abspielen.“","operator.content.purrche.name":"Purrchena","operator.content.purrche.intro":"„Jetzt werde ich … Miau-si!…Huch, wieso schlafe ich schon wieder?!“ \\nPurrchena ist ein riesiger Fan von Nachtisch und die Botschafterin der Katastrophenhilfe f\xfcr \xc6therside-Umweltauswirkungssyndrome. Auf Empfehlung der Talos-II Allgemeinen Handelskammer (TAHK) trat sie in die Gesch\xe4ftsstelle von Endfield Industries ein und ist seitdem die Verbindungsperson zwischen Endfield und der TAHK im Bereich des \xc6therside-Syndroms. \\nAls Purrchena zum ersten Mal ins Rampenlicht trat, zeigte ihr die Liebe und F\xfcrsorge, die ihr die Menschen entgegenbrachten, welche Verantwortung sie trug. Doch nachdem sie Sprecherin der Stiftung geworden war und an der Seite der Menschen stand, die mit dem \xc6therside-Syndrom leben, wurde ihr klar, wie wenig sie tun konnte. Auch wenn das \xc6therside-Syndrom oft dazu f\xfchrte, dass sie ohne Vorwarnung einschlief, machte sie sich jedes Mal, wenn sie wieder aufwachte, erneut auf den Weg und trug die Liebe aller mit sich. Auf ihre ganz eigene Art sorgt Purrchena daf\xfcr, dass die anderen Patienten, denen geholfen wird, weiterhin l\xe4cheln. \\n„Ich hab meine Marshmallows und meinen exotischen Trockenfl\xf6ssler … Gut, kann losgehen!“","operator.content.endministrator2.cv.en-us":"Hyoie O\'Grady","operator.content.endministrator1.cv.en-us":"Chloe Eves","operator.content.perlica.cv.en-us":"Jane Jackson","operator.content.chen.cv.en-us":"Rebecca Hanssen","operator.content.wulfgard.cv.en-us":"Jacopo Calatroni","operator.content.arclight.cv.en-us":"Andrea Gatchalian","operator.content.ember.cv.en-us":"Rhiannon Moushall","operator.content.xaihi.cv.en-us":"Elsie Lovelock","operator.content.avywenna.cv.en-us":"Sheena May","operator.content.gilberta.cv.en-us":"Anna Devlin","operator.content.snowshine.cv.en-us":"Stephanie Southerland","operator.content.lifeng.cv.en-us":"Yung-I Chang","operator.content.laevatain.cv.en-us":"Kira Buckland","operator.content.yvonne.cv.en-us":"Clare Louise Connolly","operator.content.dapan.cv.en-us":"Jon Xu","operator.content.ardelia.cv.en-us":"Lindsay Sheppard","operator.content.akekuri.cv.en-us":"Shu Uchida","operator.content.catcher.cv.en-us":"Kevin Andrew Rivera","operator.content.estella.cv.en-us":"Risa Mei","operator.content.fluorite.cv.en-us":"Katiana Sarkissian","operator.content.antal.cv.en-us":"Jacob Craner","operator.content.alesh.cv.en-us":"Heitor Assali","operator.content.lastrite.cv.en-us":"Amber Hood","operator.content.pogranichnik.cv.en-us":"Sergey Ponomaryov","operator.content.tangtang.cv.en-us":"Jing Chen","operator.content.rossi.cv.en-us":"Giada Sabellico","operator.content.zhuangfy.cv.en-us":"Molly Zhang","operator.content.mifu.cv.en-us":"Rao Zijun","operator.content.camille.cv.en-us":"Aleks Le","operator.content.lizhiyan.cv.en-us":"Julia Gu","operator.content.liino.cv.en-us":"Maddie Matsumoto","operator.content.typhoea.cv.en-us":"Hanna Johansson","operator.content.purrche.cv.en-us":"Christine Marie Cabanos"}'),g={src:"https://web-static.hg-cdn.com/endfield/official-v4/_next/static/media/de-de.7529ebef.png"},A={lang:"de-de",text:p,font:h,langs:i.YZ,components:{footer:t.A,SvgLogo:s.A},data:{share:[{key:"twitter",url:"https://x.com/AKEndfieldDE",icon:c.A},{key:"tiktok",url:"https://www.tiktok.com/@akendfielden",icon:d.A},{key:"facebook",url:"https://www.facebook.com/ArknightsEndfield",icon:o.A},{key:"youtube",url:"https://www.youtube.com/channel/UCowPaVRBzg8CE6K4CB6LJfw",icon:u.A},{key:"discord",url:"https://discord.gg/akendfield",icon:r.A},{key:"skport",url:"https://skport.com?hg_media=endfield_official",icon:l.A}],shop:[{key:"appStore",url:"https://apps.apple.com/app/arknights-endfield/id6752642477"},{key:"googlePlay",url:"https://play.google.com/store/apps/details?id=com.gryphline.endfield.gp"},null,null,{key:"ps5",url:"https://store.playstation.com/concept/10009205/"},{key:"windows",url:"https://launcher.gryphline.com/launcher/get_latest_launcher?appcode=TiaytKBUIEdoEwRT&ta=endfield&channel=6&sub_channel=6"},{key:"gpg",url:"https://play.google.com/pc-store/games/details?id=com.gryphline.endfield.gp"},{key:"epic",url:"https://store.epicgames.com/p/arknightsendfield-f0f167"}],operator:m},images:{"bulletin.news":g.src,"bulletin.events":g.src,"bulletin.notices":g.src,"shop.reg.appStore":"https://web-static.hg-cdn.com/endfield/official-v4/_next/static/media/appStore.0a91a829.png","shop.reg.googlePlay":"https://web-static.hg-cdn.com/endfield/official-v4/_next/static/media/google.54c451d0.png","shop.get.appStore":"https://web-static.hg-cdn.com/endfield/official-v4/_next/static/media/appStore.23d0ac0d.png","shop.get.googlePlay":"https://web-static.hg-cdn.com/endfield/official-v4/_next/static/media/googlePlay.e9e02fe5.png","home.v1d4Cele":n(88351).A.src,"home.pageTitle":n(28457).A.src,"calendar.title":n(52431).A.src,"calendar.timeline":n(17526).A.src,"calendar.content":n(45546).A.src}}};
